-- ─────────────────────────────────────────────────────────────────────────────
-- SETTINGS  ·  the only part of this file intended to be edited
-- ─────────────────────────────────────────────────────────────────────────────

-- The gate. Nothing is created while this is FALSE.
SET MONITOR_APPROVE = FALSE;

-- Where to build. Blank means the database currently in use.
SET MONITOR_TARGET_DB = '';
SET MONITOR_SCHEMA    = 'OBSERVABILITY_MONITOR';

-- How far back the views look.
SET MONITOR_WINDOW_DAYS = 14;

-- Warehouse for the Streamlit app. Blank means the warehouse currently in use.
SET MONITOR_APP_WAREHOUSE = '';

-- Notification integration name (must already exist). Blank disables delivery.
SET MONITOR_NOTIFICATION_INTEGRATION = '';

-- Tables to monitor with DMFs. Comma-separated FQNs, or '*' for auto (top-N).
-- BLANK IS NOT "OFF": blank and '*' both take the auto path and attach FRESHNESS
-- + ROW_COUNT to the top-N tables by importance, account-wide. Name the tables
-- here to keep the monitoring inside a scope you chose.
SET MONITOR_TABLES = '';

-- Top-N tables for zero-config auto-selection (Section 10).
SET MONITOR_TOP_N = 50;

-- How often the attached DMFs evaluate. This is the credit dial: every table on
-- the list is evaluated on this interval, so halving it doubles the monthly
-- figure the build reports. Written as 'N MINUTE'; anything else falls back to
-- 60 so the run-rate arithmetic always has a real interval to divide by.
SET MONITOR_DMF_SCHEDULE = '60 MINUTE';

-- Which tier this build is. Only PRODUCTION leaves the DMF schedule running.
-- Below it the metrics are attached and the schedule is set so Snowflake reports
-- it live, then suspended again before the block ends, so a look-around build
-- cannot walk away leaving a recurring serverless charge on someone's tables.
SET MONITOR_DEPLOY_TIER = 'SAMPLE';

-- Whether to create alert objects. FALSE means discovery + views only.
SET MONITOR_ALERTS = FALSE;

-- Whether to create Cortex agent stored procedures.
SET MONITOR_AGENTS = FALSE;

-- Internal. Do not edit; these carry state between blocks.
SET MONITOR_SIGNALS = '';
SET MONITOR_PLAN    = '';

-- ---------------------------------------------------------------------------
-- BLOCK 3 SETTINGS · upstream collectors (the pull side)
-- Separate gate: this block needs account-level privileges and credentials,
-- which the rest of the script does not.
-- ---------------------------------------------------------------------------
-- Independent gate. TRUE builds the collectors.
SET MONITOR_UPSTREAM = FALSE;

-- Name of an EXTERNAL ACCESS INTEGRATION this role may USAGE. Leave blank to
-- have the block emit the DDL for whoever holds ACCOUNTADMIN.
SET MONITOR_UPSTREAM_EAI = '';

-- Seed the registry with worked examples (Airflow, postgres_exporter, Confluent)
-- so the shape is obvious. Examples are created DISABLED.
SET MONITOR_UPSTREAM_SEED = TRUE;


-- ─────────────────────────────────────────────────────────────────────────────
-- BLOCK 0 · PRE-FLIGHT
-- Answers only the questions that decide whether the rest can run.
-- Creates nothing. Reads no business data.
-- ─────────────────────────────────────────────────────────────────────────────
EXECUTE IMMEDIATE $$
DECLARE
  res RESULTSET;
BEGIN
  LET db STRING := COALESCE(NULLIF($MONITOR_TARGET_DB::VARCHAR, ''), CURRENT_DATABASE());
  LET wh STRING := COALESCE(NULLIF($MONITOR_APP_WAREHOUSE::VARCHAR, ''), CURRENT_WAREHOUSE());
  LET notif_name STRING := NULLIF($MONITOR_NOTIFICATION_INTEGRATION::VARCHAR, '');

  -- 1. Can Block 3 create its schema in that database?
  LET db_ok BOOLEAN := FALSE;
  IF (:db IS NOT NULL) THEN
    BEGIN
      EXECUTE IMMEDIATE 'SHOW GRANTS ON DATABASE "' || :db || '"';
      db_ok := (SELECT COUNT_IF("privilege" IN ('CREATE SCHEMA','OWNERSHIP')
                                AND "granted_to" = 'ROLE'
                                AND IS_ROLE_IN_SESSION("grantee_name")) > 0
                FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
    EXCEPTION WHEN OTHER THEN db_ok := FALSE;
    END;
  END IF;

  -- 2. ACCOUNT_USAGE readable?
  LET au_ok BOOLEAN := FALSE;
  BEGIN
    LET probe INT := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY
                      WHERE START_TIME >= DATEADD(day, -1, CURRENT_TIMESTAMP()));
    au_ok := TRUE;
  EXCEPTION WHEN OTHER THEN au_ok := FALSE;
  END;

  -- 3. APPLY DATA METRIC FUNCTION privilege?
  LET dmf_ok BOOLEAN := FALSE;
  BEGIN
    EXECUTE IMMEDIATE 'SHOW GRANTS TO ROLE ' || CURRENT_ROLE();
    dmf_ok := (SELECT COUNT_IF("privilege" = 'APPLY DATA METRIC FUNCTION') > 0
               FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
  EXCEPTION WHEN OTHER THEN dmf_ok := FALSE;
  END;

  -- 4. DATA_LINEAGE_VIEWER database role accessible?
  LET lineage_ok BOOLEAN := FALSE;
  BEGIN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM TABLE(SNOWFLAKE.CORE.GET_LINEAGE(''' 
      || COALESCE(:db, CURRENT_DATABASE()) || '.INFORMATION_SCHEMA.TABLES'', ''TABLE'', '''', 1, ''downstream''))';
    lineage_ok := TRUE;
  EXCEPTION WHEN OTHER THEN lineage_ok := FALSE;
  END;

  -- 5. Notification integration exists?
  LET notif_ok BOOLEAN := FALSE;
  LET notif_msg STRING := 'not supplied';
  IF (:notif_name IS NOT NULL) THEN
    BEGIN
      EXECUTE IMMEDIATE 'SHOW NOTIFICATION INTEGRATIONS LIKE ''' || :notif_name || '''';
      LET ni_cnt INT := (SELECT COUNT(*) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
      notif_ok := (:ni_cnt > 0);
      notif_msg := IFF(:notif_ok, 'FOUND', 'NOT FOUND — alerts will log to event table only');
    EXCEPTION WHEN OTHER THEN
      notif_ok := FALSE;
      notif_msg := 'ERROR probing — alerts will log to event table only';
    END;
  END IF;

  -- 6. Event table configured?
  LET evt STRING := NULL;
  BEGIN
    EXECUTE IMMEDIATE 'SHOW PARAMETERS LIKE ''EVENT_TABLE'' IN ACCOUNT';
    evt := (SELECT NULLIF(MAX("value"), '') FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
  EXCEPTION WHEN OTHER THEN evt := NULL;
  END;

  -- 7. Approval flag
  LET approved BOOLEAN := FALSE;
  BEGIN
    approved := (SELECT TRY_CAST($MONITOR_APPROVE::VARCHAR AS BOOLEAN));
  EXCEPTION WHEN OTHER THEN approved := FALSE;
  END;

  res := (
    SELECT 1 AS ord, 'current_role' AS check_name, CURRENT_ROLE()::VARCHAR AS value, '' AS action_if_missing
    UNION ALL SELECT 2, 'warehouse',
      COALESCE(:wh || ' — usable', '(none — required)'),
      IFF(:wh IS NULL, 'USE WAREHOUSE <one you can use>;', '')
    UNION ALL SELECT 3, 'build_database',
      COALESCE(:db, '(none — required)'),
      IFF(:db IS NULL, 'USE DATABASE <where the monitor should live>;', '')
    UNION ALL SELECT 4, 'can_create_schema_here',
      IFF(:db_ok, 'YES — in ' || :db, 'not visible on ' || COALESCE(:db, '(none)')),
      IFF(:db_ok, '', 'GRANT CREATE SCHEMA ON DATABASE '
                   || COALESCE(:db, '<db>') || ' TO ROLE ' || CURRENT_ROLE() || ';')
    UNION ALL SELECT 5, 'account_usage_readable',
      IFF(:au_ok, 'YES', 'NO — most panels will be unavailable'),
      IFF(:au_ok, '', 'GRANT IMPORTED PRIVILEGES ON DATABASE SNOWFLAKE TO ROLE '
                   || CURRENT_ROLE() || ';')
    UNION ALL SELECT 6, 'apply_dmf_privilege',
      IFF(:dmf_ok, 'YES', 'NO — DMF attachment will fail'),
      IFF(:dmf_ok, '', 'GRANT APPLY DATA METRIC FUNCTION ON ACCOUNT TO ROLE '
                   || CURRENT_ROLE() || ';')
    UNION ALL SELECT 7, 'data_lineage_viewer',
      IFF(:lineage_ok, 'YES — lineage queries will work', 'NO — lineage panel unavailable'),
      IFF(:lineage_ok, '', 'GRANT DATABASE ROLE SNOWFLAKE.DATA_LINEAGE_VIEWER TO ROLE '
                   || CURRENT_ROLE() || ';')
    UNION ALL SELECT 8, 'notification_integration',
      CASE WHEN :notif_name IS NULL THEN 'not supplied — alerts log to event table only'
           ELSE :notif_name || ' — ' || :notif_msg END,
      IFF(:notif_name IS NOT NULL AND NOT :notif_ok,
          'CREATE NOTIFICATION INTEGRATION or correct the name.', '')
    UNION ALL SELECT 9, 'event_table_configured',
      COALESCE(:evt, 'none set on this account'),
      IFF(:evt IS NULL, 'Optional. Without one there is no log panel; everything else still works.', '')
    UNION ALL SELECT 10, 'approval_flag',
      IFF(:approved, 'TRUE — Block 3 WILL BUILD', 'FALSE — Block 3 creates nothing'),
      IFF(:approved, '', 'To build: change SET MONITOR_APPROVE to TRUE and run the file again.')
    ORDER BY ord
  );
  RETURN TABLE(res);
END;
$$;


-- ─────────────────────────────────────────────────────────────────────────────
-- BLOCK 1 · DISCOVERY  (reads metadata and row counts only — creates nothing)
--
-- Probes each monitoring signal separately, so one missing privilege costs one
-- panel rather than the whole run. Three outcomes per signal:
--
--   AVAILABLE   readable and populated in the window  → becomes a panel
--   EMPTY       readable but nothing in the window    → skipped, and said so
--   NO ACCESS   the role cannot read it               → skipped, and said so
--
-- Also computes table IMPORTANCE SCORE for zero-config (Section 10).
-- ─────────────────────────────────────────────────────────────────────────────
EXECUTE IMMEDIATE $$
DECLARE
  res RESULTSET;
BEGIN
  LET w INT := COALESCE((SELECT TRY_CAST($MONITOR_WINDOW_DAYS::VARCHAR AS INT)), 14);
  LET top_n INT := COALESCE((SELECT TRY_CAST($MONITOR_TOP_N::VARCHAR AS INT)), 50);
  LET sig OBJECT := OBJECT_CONSTRUCT();
  LET cnt OBJECT := OBJECT_CONSTRUCT();
  LET n   INT    := 0;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 1: task_runs
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY
          WHERE SCHEDULED_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'task_runs', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'task_runs', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'task_runs', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'task_runs', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 2: dynamic_table_refreshes
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.DYNAMIC_TABLE_REFRESH_HISTORY
          WHERE REFRESH_START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'dynamic_table_refreshes', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'dynamic_table_refreshes', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'dynamic_table_refreshes', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'dynamic_table_refreshes', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 3: copy_loads
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.COPY_HISTORY
          WHERE LAST_LOAD_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'copy_loads', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'copy_loads', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'copy_loads', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'copy_loads', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 4: pipe_usage
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.PIPE_USAGE_HISTORY
          WHERE START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'pipe_usage', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'pipe_usage', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'pipe_usage', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'pipe_usage', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 5: streaming_channels
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.SNOWPIPE_STREAMING_CLIENT_HISTORY
          WHERE EVENT_TIMESTAMP >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'streaming_channels', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'streaming_channels', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'streaming_channels', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'streaming_channels', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 6: query_pressure
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY
          WHERE START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP())
            AND (BYTES_SPILLED_TO_REMOTE_STORAGE > 0 OR QUEUED_OVERLOAD_TIME > 0
                 OR EXECUTION_STATUS = 'FAIL'));
    sig := OBJECT_INSERT(:sig, 'query_pressure', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'query_pressure', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'query_pressure', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'query_pressure', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 7: wh_credits
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY
          WHERE START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'wh_credits', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'wh_credits', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'wh_credits', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'wh_credits', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 8: dmf_results
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.LOCAL.DATA_QUALITY_MONITORING_RESULTS
          WHERE MEASUREMENT_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'dmf_results', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'dmf_results', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'dmf_results', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'dmf_results', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 9: dmf_anomalies
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS
          WHERE IS_ANOMALY = TRUE
            AND MEASUREMENT_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'dmf_anomalies', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'dmf_anomalies', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'dmf_anomalies', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'dmf_anomalies', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 10: table_dml
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.TABLE_DML_HISTORY
          WHERE START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'table_dml', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'table_dml', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'table_dml', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'table_dml', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 11: lineage
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    LET lineage_db STRING := COALESCE(NULLIF($MONITOR_TARGET_DB::VARCHAR, ''), CURRENT_DATABASE());
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM TABLE(SNOWFLAKE.CORE.GET_LINEAGE('''
      || :lineage_db || '.INFORMATION_SCHEMA.TABLES'', ''TABLE'', '''', 1, ''downstream''))';
    n := (SELECT $1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
    sig := OBJECT_INSERT(:sig, 'lineage', 'AVAILABLE', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'lineage', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'lineage', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'lineage', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 12: access_history
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY
          WHERE QUERY_START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'access_history', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'access_history', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'access_history', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'access_history', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 13: login_events
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.LOGIN_HISTORY
          WHERE EVENT_TIMESTAMP >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'login_events', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'login_events', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'login_events', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'login_events', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 14: alert_history
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.ALERT_HISTORY
          WHERE SCHEDULED_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'alert_history', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'alert_history', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'alert_history', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'alert_history', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 15: event_log (dynamic table name from account parameter)
  -- ───────────────────────────────────────────────────────────────────────────
  LET evt STRING := NULL;
  BEGIN
    EXECUTE IMMEDIATE 'SHOW PARAMETERS LIKE ''EVENT_TABLE'' IN ACCOUNT';
    evt := (SELECT NULLIF(MAX("value"), '') FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
    IF (:evt IS NULL) THEN
      sig := OBJECT_INSERT(:sig, 'event_log', 'NOT CONFIGURED', TRUE);
      cnt := OBJECT_INSERT(:cnt, 'event_log', 0, TRUE);
    ELSE
      EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM "' 
        || SPLIT_PART(:evt, '.', 1) || '"."' 
        || SPLIT_PART(:evt, '.', 2) || '"."' 
        || SPLIT_PART(:evt, '.', 3) || '"'
        || ' WHERE TIMESTAMP >= DATEADD(day, -' || :w || ', CURRENT_TIMESTAMP())';
      n := (SELECT $1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
      sig := OBJECT_INSERT(:sig, 'event_log', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
      cnt := OBJECT_INSERT(:cnt, 'event_log', :n, TRUE);
      sig := OBJECT_INSERT(:sig, 'event_table_name', :evt, TRUE);
    END IF;
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'event_log', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'event_log', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 16: notification_integrations
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    EXECUTE IMMEDIATE 'SHOW NOTIFICATION INTEGRATIONS';
    n := (SELECT COUNT(*) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
    sig := OBJECT_INSERT(:sig, 'notification_integrations', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'notification_integrations', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'notification_integrations', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'notification_integrations', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 17: ext_monitor_footprint (an external monitoring tool query tag detection)
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY
          WHERE QUERY_TAG ILIKE '%mc_monitor_id=%'
            AND START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'ext_monitor_footprint', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'ext_monitor_footprint', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'ext_monitor_footprint', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'ext_monitor_footprint', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 18: cortex_agents (SHOW AGENTS + trace readability)
  -- ───────────────────────────────────────────────────────────────────────────
  LET agent_count INT := 0;
  LET traces_ok BOOLEAN := FALSE;
  BEGIN
    EXECUTE IMMEDIATE 'SHOW AGENTS';
    agent_count := (SELECT COUNT(*) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
    IF (:agent_count > 0) THEN
      LET first_agent_db STRING := (SELECT "database_name" FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) LIMIT 1);
      LET first_agent_schema STRING := (SELECT "schema_name" FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) LIMIT 1);
      LET first_agent_name STRING := (SELECT "name" FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) LIMIT 1);
      BEGIN
        EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM TABLE(SNOWFLAKE.LOCAL.GET_AI_OBSERVABILITY_EVENTS('''
          || :first_agent_db || ''',''' || :first_agent_schema || ''',''' || :first_agent_name || ''',''CORTEX AGENT''))';
        traces_ok := TRUE;
      EXCEPTION WHEN OTHER THEN traces_ok := FALSE;
      END;
    END IF;
    IF (:agent_count > 0 AND :traces_ok) THEN
      sig := OBJECT_INSERT(:sig, 'cortex_agents', 'AVAILABLE', TRUE);
    ELSEIF (:agent_count > 0) THEN
      sig := OBJECT_INSERT(:sig, 'cortex_agents', 'PARTIAL', TRUE);
    ELSE
      sig := OBJECT_INSERT(:sig, 'cortex_agents', 'EMPTY', TRUE);
    END IF;
    cnt := OBJECT_INSERT(:cnt, 'cortex_agents', :agent_count, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'cortex_agents', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'cortex_agents', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 19: warehouse_churn (SUSPEND/RESUME events)
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_EVENTS_HISTORY
          WHERE EVENT_NAME IN ('SUSPEND_WAREHOUSE','RESUME_WAREHOUSE')
            AND TIMESTAMP >= DATEADD(day, -:w, CURRENT_TIMESTAMP()));
    sig := OBJECT_INSERT(:sig, 'warehouse_churn', IFF(:n > 0, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'warehouse_churn', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'warehouse_churn', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'warehouse_churn', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Signal 20: bi_layer (query pressure partitioned by client application)
  -- CLIENT_APPLICATION_ID lives in SESSIONS, not QUERY_HISTORY.
  -- ───────────────────────────────────────────────────────────────────────────
  BEGIN
    n := (SELECT COUNT(DISTINCT s.CLIENT_APPLICATION_ID)
          FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY q
          JOIN SNOWFLAKE.ACCOUNT_USAGE.SESSIONS s ON q.SESSION_ID = s.SESSION_ID
          WHERE q.START_TIME >= DATEADD(day, -:w, CURRENT_TIMESTAMP())
            AND s.CLIENT_APPLICATION_ID IS NOT NULL);
    sig := OBJECT_INSERT(:sig, 'bi_layer', IFF(:n > 1, 'AVAILABLE', 'EMPTY'), TRUE);
    cnt := OBJECT_INSERT(:cnt, 'bi_layer', :n, TRUE);
  EXCEPTION WHEN OTHER THEN
    sig := OBJECT_INSERT(:sig, 'bi_layer', 'NO ACCESS', TRUE);
    cnt := OBJECT_INSERT(:cnt, 'bi_layer', 0, TRUE);
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- Table IMPORTANCE SCORE for zero-config (Section 10)
  -- Computes: read frequency, distinct consumers, downstream deps, DML recency
  -- Emits ranked top-N candidate list + DML ops/hour for the ceiling check.
  -- ───────────────────────────────────────────────────────────────────────────
  LET importance ARRAY := ARRAY_CONSTRUCT();
  BEGIN
    LET imp_sql STRING := '
      WITH reads AS (
        SELECT
          obj.value:objectName::STRING AS table_fqn,
          COUNT(*) AS read_count,
          COUNT(DISTINCT ah.USER_NAME) AS consumer_count
        FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY ah,
             LATERAL FLATTEN(input => ah.BASE_OBJECTS_ACCESSED) obj
        WHERE ah.QUERY_START_TIME >= DATEADD(day, -' || :w || ', CURRENT_TIMESTAMP())
          AND obj.value:objectDomain::STRING = ''Table''
        GROUP BY 1
      ),
      dml AS (
        SELECT
          DATABASE_NAME || ''.'' || SCHEMA_NAME || ''.'' || TABLE_NAME AS table_fqn,
          MAX(START_TIME) AS last_dml,
          COUNT(*) AS dml_ops,
          COUNT(*) / GREATEST(DATEDIFF(hour, MIN(START_TIME), CURRENT_TIMESTAMP()), 1) AS dml_ops_per_hour
        FROM SNOWFLAKE.ACCOUNT_USAGE.TABLE_DML_HISTORY
        WHERE START_TIME >= DATEADD(day, -' || :w || ', CURRENT_TIMESTAMP())
        GROUP BY 1
      ),
      scored AS (
        SELECT
          r.table_fqn,
          r.read_count,
          r.consumer_count,
          COALESCE(d.dml_ops_per_hour, 0) AS dml_ops_per_hour,
          DATEDIFF(hour, COALESCE(d.last_dml, DATEADD(day, -' || :w || ', CURRENT_TIMESTAMP())), CURRENT_TIMESTAMP()) AS hours_since_dml,
          (r.read_count * 0.4) + (r.consumer_count * 30) + (1.0 / GREATEST(DATEDIFF(hour, COALESCE(d.last_dml, DATEADD(day, -' || :w || ', CURRENT_TIMESTAMP())), CURRENT_TIMESTAMP()), 1) * 100) AS importance_score
        FROM reads r
        LEFT JOIN dml d ON r.table_fqn = d.table_fqn
      )
      SELECT table_fqn, read_count, consumer_count, dml_ops_per_hour, importance_score
      FROM scored
      ORDER BY importance_score DESC
      LIMIT ' || :top_n;

    EXECUTE IMMEDIATE :imp_sql;
    importance := (SELECT ARRAY_AGG(OBJECT_CONSTRUCT(
        'table_fqn', $1, 'read_count', $2, 'consumer_count', $3,
        'dml_ops_per_hour', $4, 'importance_score', $5
      )) FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())));
  EXCEPTION WHEN OTHER THEN
    importance := ARRAY_CONSTRUCT();
  END;

  -- ───────────────────────────────────────────────────────────────────────────
  -- HANDOFF: pass findings to Block 2
  -- Backslashes FIRST, then single-quotes (order matters).
  -- ───────────────────────────────────────────────────────────────────────────
  LET payload STRING := REPLACE(REPLACE(TO_JSON(OBJECT_CONSTRUCT(
      'sig', :sig, 'cnt', :cnt, 'window_days', :w,
      'importance', :importance)), '\\', '\\\\'), '''', '''''');

  -- Session variables are capped at 16,384 bytes. The signal map is small, but the
  -- importance list grows with MONITOR_TOP_N and is the one part that can push this
  -- payload over the edge. Fail loudly with an actionable message rather than
  -- letting the SET fail with an opaque 002126.
  IF (LENGTH(:payload) > 15000) THEN
    res := (SELECT 'PAYLOAD TOO LARGE' AS signal, 'ERROR' AS status,
                   LENGTH(:payload) AS rows_in_window,
                   'Discovery findings are ' || LENGTH(:payload) || ' bytes but a Snowflake session '
                || 'variable holds at most 16384. Lower MONITOR_TOP_N (currently '
                || $MONITOR_TOP_N || ') and run the file again. Around 50 tables is safe.' AS meaning);
    RETURN TABLE(res);
  END IF;

  EXECUTE IMMEDIATE 'SET MONITOR_SIGNALS = ''' || :payload || '''';

  IF ((SELECT TRY_PARSE_JSON(GETVARIABLE('MONITOR_SIGNALS')) IS NULL)) THEN
    res := (SELECT 'HANDOFF FAILED' AS signal, '' AS status, 0 AS rows_in_window,
                   'Discovery ran but could not pass its findings to Block 2. This is a bug '
                || 'in this script, not a problem with your account.' AS meaning);
    RETURN TABLE(res);
  END IF;

  res := (
    SELECT k.KEY::STRING AS signal,
           :sig[k.KEY]::STRING AS status,
           COALESCE(:cnt[k.KEY]::INT, 0) AS rows_in_window,
           CASE :sig[k.KEY]::STRING
             WHEN 'AVAILABLE'      THEN 'becomes a panel in the app'
             WHEN 'EMPTY'          THEN 'readable, but nothing in the last ' || :w || ' days — no panel'
             WHEN 'NO ACCESS'      THEN 'this role cannot read the source — no panel'
             WHEN 'NOT CONFIGURED' THEN 'no event table is set on this account — no log panel'
             WHEN 'PARTIAL'        THEN 'agents found but traces may not be readable'
             ELSE '' END AS meaning
    FROM TABLE(FLATTEN(input => :sig)) k
    WHERE k.KEY::STRING NOT IN ('event_table_name')
    ORDER BY IFF(:sig[k.KEY]::STRING = 'AVAILABLE', 0, 1), signal
  );
  RETURN TABLE(res);
END;
$$;


-- ─────────────────────────────────────────────────────────────────────────────
-- BLOCK 2 · THE PLAN AND THE BUILD
-- Generates every statement and PRINTS them. Creates nothing while the approval
-- flag is FALSE. When the flag is TRUE it executes the same list it printed.
--
-- Plan and build are ONE block on purpose. Session variables are capped at 16,384
-- bytes, and this plan is far larger, so handing the statement list from a
-- separate planning block to a separate build block via SET/GETVARIABLE cannot
-- work. Keeping them together also guarantees the build runs exactly the plan
-- that was just printed, in this session, rather than a stale one.
-- ─────────────────────────────────────────────────────────────────────────────
EXECUTE IMMEDIATE $$
DECLARE
  res RESULTSET;
BEGIN
  LET found VARIANT := (SELECT TRY_PARSE_JSON(GETVARIABLE('MONITOR_SIGNALS')));
  IF (:found IS NULL) THEN
    res := (SELECT 0 AS step, 'BLOCKED' AS action,
                   'Block 1 has not run in this session. Run the file top to bottom.' AS statement);
    RETURN TABLE(res);
  END IF;

  LET sig        VARIANT := :found:sig;
  LET cnt        VARIANT := :found:cnt;
  LET w          INT     := :found:window_days::INT;
  LET importance ARRAY   := COALESCE(:found:importance::ARRAY, ARRAY_CONSTRUCT());
  LET db         STRING  := COALESCE(NULLIF($MONITOR_TARGET_DB::VARCHAR, ''), CURRENT_DATABASE());
  LET sch        STRING  := $MONITOR_SCHEMA::VARCHAR;
  LET wh         STRING  := COALESCE(NULLIF($MONITOR_APP_WAREHOUSE::VARCHAR, ''), CURRENT_WAREHOUSE());
  LET notif      STRING  := (SELECT NULLIF($MONITOR_NOTIFICATION_INTEGRATION::VARCHAR, ''));
  LET mon_tables STRING  := (SELECT NULLIF($MONITOR_TABLES::VARCHAR, ''));
  LET top_n      INT     := COALESCE((SELECT TRY_CAST($MONITOR_TOP_N::VARCHAR AS INT)), 50);
  LET do_alerts  BOOLEAN := (SELECT TRY_CAST($MONITOR_ALERTS::VARCHAR AS BOOLEAN));
  LET do_agents  BOOLEAN := (SELECT TRY_CAST($MONITOR_AGENTS::VARCHAR AS BOOLEAN));
  LET evt_table  STRING  := :found:event_table_name::STRING;

  LET tier STRING := UPPER(COALESCE((SELECT NULLIF($MONITOR_DEPLOY_TIER::VARCHAR, '')), 'SAMPLE'));
  -- The interval is parsed out of the setting rather than trusted as a string,
  -- and the string that gets SET is rebuilt from the parsed number. That way the
  -- schedule on the table and the divisor in the run-rate cannot drift apart --
  -- a cron in the setting would otherwise be priced as if it were 60 minutes.
  LET dmf_sched_raw STRING := COALESCE((SELECT NULLIF($MONITOR_DMF_SCHEDULE::VARCHAR, '')), '60 MINUTE');
  LET dmf_min INT := GREATEST(COALESCE(TRY_CAST(SPLIT_PART(TRIM(:dmf_sched_raw), ' ', 1) AS INT), 60), 1);
  LET dmf_sched STRING := :dmf_min || ' MINUTE';

  IF (:db IS NULL) THEN
    res := (SELECT 0 AS step, 'BLOCKED' AS action,
                   'No database selected. Run USE DATABASE or set MONITOR_TARGET_DB.' AS statement);
    RETURN TABLE(res);
  END IF;
  IF (:wh IS NULL) THEN
    res := (SELECT 0 AS step, 'BLOCKED' AS action,
                   'No warehouse selected. Run USE WAREHOUSE or set MONITOR_APP_WAREHOUSE.' AS statement);
    RETURN TABLE(res);
  END IF;

  LET tgt   STRING := :db || '.' || :sch;
  LET since STRING := 'DATEADD(day, -' || :w || ', CURRENT_TIMESTAMP())';
  LET stmts ARRAY  := ARRAY_CONSTRUCT();

  stmts := ARRAY_APPEND(:stmts, 'CREATE SCHEMA IF NOT EXISTS ' || :tgt);
  stmts := ARRAY_APPEND(:stmts, 'CREATE STAGE IF NOT EXISTS ' || :tgt || '.APP_STAGE');
  stmts := ARRAY_APPEND(:stmts, 'CREATE TABLE IF NOT EXISTS ' || :tgt || '.ATTACHED_DMF_REGISTRY (TABLE_FQN VARCHAR, DMF_NAME VARCHAR, ARGUMENTS VARCHAR, ATTACHED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP())');

  -- ── What this build leaves RUNNING ─────────────────────────────────────────
  -- Created here, ahead of the DMF section, because :stmts executes in array
  -- order and the INSERT that fills this table is appended down there. The two
  -- views over it are created after those rows land, so they are worth reading.
  --
  -- This solution predates the harness, so nothing emits these for it. The column
  -- list is the harness's, unchanged, so the app and the packet read this the same
  -- way they read every other solution's.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE TABLE IF NOT EXISTS ' || :tgt || '.STANDING_WORKLOAD ('
 || 'KIND VARCHAR, OBJECT_NAME VARCHAR, CADENCE VARCHAR, '
 || 'RUNS_PER_MONTH NUMBER(38,4), SECONDS_PER_RUN NUMBER(38,4), '
 || 'WAREHOUSE_CREDITS_PER_HOUR NUMBER(38,4), '
 || 'MEASURED_INPUT VARCHAR, BASIS VARCHAR, '
 || 'INSTALLED_AT TIMESTAMP_NTZ)');
  -- Cleared per build. A monthly figure that climbs every time the script is
  -- re-run is the kind of wrong that gets quoted before anyone checks it.
  stmts := ARRAY_APPEND(:stmts, 'DELETE FROM ' || :tgt || '.STANDING_WORKLOAD');

  -- Snowflake's own answer about each attachment, captured at build time. Below
  -- PRODUCTION the schedule is suspended again a few statements later, so without
  -- this there would be no evidence the monitoring was ever live -- only a claim.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE TABLE IF NOT EXISTS ' || :tgt || '.DMF_SCHEDULE_PROOF ('
 || 'TABLE_FQN VARCHAR, METRIC_NAME VARCHAR, SCHEDULE VARCHAR, '
 || 'SCHEDULE_STATUS VARCHAR, OBSERVED_AT TIMESTAMP_NTZ)');
  stmts := ARRAY_APPEND(:stmts, 'DELETE FROM ' || :tgt || '.DMF_SCHEDULE_PROOF');

  -- Which tier ran, so the run-rate can be read against the build that produced
  -- it. A figure from a SAMPLE build describes a schedule that is no longer set.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE TABLE IF NOT EXISTS ' || :tgt || '.RUN_LEDGER ('
 || 'TIER VARCHAR, STARTED_AT TIMESTAMP_NTZ)');
  stmts := ARRAY_APPEND(:stmts,
    'INSERT INTO ' || :tgt || '.RUN_LEDGER (TIER, STARTED_AT) SELECT '''
 || :tier || ''', CURRENT_TIMESTAMP()');

  -- ── Views: Pipeline Health ─────────────────────────────────────────────────
  IF (:sig:task_runs::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_TASK_FAILURES COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT SCHEDULED_TIME, COMPLETED_TIME, NAME AS TASK_NAME, DATABASE_NAME, SCHEMA_NAME, STATE, ERROR_CODE, ERROR_MESSAGE, ROOT_TASK_ID, GRAPH_VERSION, RUN_ID FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE STATE = ''FAILED'' AND SCHEDULED_TIME >= ' || :since);
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_TASK_RELIABILITY COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''hour'', SCHEDULED_TIME) AS HOUR_BUCKET, DATABASE_NAME, SCHEMA_NAME, NAME AS TASK_NAME, COUNT_IF(STATE = ''SUCCEEDED'') AS SUCCEEDED, COUNT_IF(STATE = ''FAILED'') AS FAILED, COUNT_IF(STATE = ''CANCELLED'') AS CANCELLED, COUNT(*) AS TOTAL_RUNS, ROUND(DIV0(COUNT_IF(STATE = ''SUCCEEDED''), COUNT(*)) * 100, 2) AS SUCCESS_RATE_PCT FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE SCHEDULED_TIME >= ' || :since || ' GROUP BY 1, 2, 3, 4');
  END IF;

  IF (:sig:dynamic_table_refreshes::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_DT_REFRESH_HEALTH COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT REFRESH_START_TIME, REFRESH_END_TIME, DATABASE_NAME, SCHEMA_NAME, NAME AS DYNAMIC_TABLE_NAME, STATE, STATE_CODE, STATE_MESSAGE, REFRESH_ACTION, TARGET_LAG_SEC, DATEDIFF(''second'', REFRESH_START_TIME, REFRESH_END_TIME) AS REFRESH_DURATION_SEC FROM SNOWFLAKE.ACCOUNT_USAGE.DYNAMIC_TABLE_REFRESH_HISTORY WHERE REFRESH_START_TIME >= ' || :since);
  END IF;

  IF (:sig:table_dml::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_TABLE_FRESHNESS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT TABLE_ID, TABLE_NAME, SCHEMA_NAME, DATABASE_NAME, START_TIME AS LAST_DML_TIME, DATEDIFF(''minute'', START_TIME, CURRENT_TIMESTAMP()) AS MINUTES_SINCE_LAST_DML, ROWS_ADDED, ROWS_REMOVED, ROWS_UPDATED FROM SNOWFLAKE.ACCOUNT_USAGE.TABLE_DML_HISTORY WHERE START_TIME >= ' || :since || ' QUALIFY ROW_NUMBER() OVER (PARTITION BY TABLE_ID ORDER BY START_TIME DESC) = 1');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_TABLE_DML_TREND COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''hour'', START_TIME) AS HOUR_BUCKET, DATABASE_NAME, SCHEMA_NAME, TABLE_NAME, SUM(ROWS_ADDED) AS ROWS_ADDED, SUM(ROWS_REMOVED) AS ROWS_REMOVED, SUM(ROWS_UPDATED) AS ROWS_UPDATED, COUNT(*) AS DML_OPERATIONS FROM SNOWFLAKE.ACCOUNT_USAGE.TABLE_DML_HISTORY WHERE START_TIME >= ' || :since || ' GROUP BY 1, 2, 3, 4');
  END IF;

  -- ── Views: Ingestion ───────────────────────────────────────────────────────
  IF (:sig:copy_loads::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_COPY_LOADS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT LAST_LOAD_TIME, TABLE_NAME, TABLE_SCHEMA_NAME AS SCHEMA_NAME, TABLE_CATALOG_NAME AS DATABASE_NAME, FILE_NAME, ROW_COUNT, ROW_PARSED, ERROR_COUNT, STATUS, PIPE_CATALOG_NAME, PIPE_SCHEMA_NAME, PIPE_NAME FROM SNOWFLAKE.ACCOUNT_USAGE.COPY_HISTORY WHERE LAST_LOAD_TIME >= ' || :since);
  END IF;

  IF (:sig:pipe_usage::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_PIPE_THROUGHPUT COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT START_TIME, END_TIME, PIPE_ID, PIPE_NAME, CREDITS_USED, BYTES_INSERTED, FILES_INSERTED, BYTES_BILLED FROM SNOWFLAKE.ACCOUNT_USAGE.PIPE_USAGE_HISTORY WHERE START_TIME >= ' || :since);
  END IF;

  IF (:sig:streaming_channels::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_STREAMING_HEALTH COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT EVENT_TIMESTAMP, CLIENT_NAME, SNOWFLAKE_PROVIDED_ID AS CHANNEL_ID, EVENT_TYPE, BLOB_SIZE_BYTES FROM SNOWFLAKE.ACCOUNT_USAGE.SNOWPIPE_STREAMING_CLIENT_HISTORY WHERE EVENT_TIMESTAMP >= ' || :since);
  END IF;

  -- ── Views: Query Performance ───────────────────────────────────────────────
  IF (:sig:query_pressure::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_QUERY_PRESSURE COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''hour'', START_TIME) AS HOUR_BUCKET, WAREHOUSE_NAME, COUNT(*) AS TOTAL_QUERIES, COUNT_IF(EXECUTION_STATUS = ''FAIL'') AS FAILED_QUERIES, COUNT_IF(BYTES_SPILLED_TO_REMOTE_STORAGE > 0) AS SPILL_QUERIES, COUNT_IF(QUEUED_OVERLOAD_TIME > 0) AS QUEUED_QUERIES, AVG(TOTAL_ELAPSED_TIME) AS AVG_ELAPSED_MS, SUM(CREDITS_USED_CLOUD_SERVICES) AS CLOUD_CREDITS FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE START_TIME >= ' || :since || ' GROUP BY 1, 2');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_SPILL_OFFENDERS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT QUERY_ID, START_TIME, USER_NAME, WAREHOUSE_NAME, WAREHOUSE_SIZE, TOTAL_ELAPSED_TIME AS ELAPSED_MS, BYTES_SPILLED_TO_LOCAL_STORAGE, BYTES_SPILLED_TO_REMOTE_STORAGE, ROWS_PRODUCED, PARTITIONS_SCANNED, PARTITIONS_TOTAL FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE BYTES_SPILLED_TO_REMOTE_STORAGE > 0 AND START_TIME >= ' || :since || ' ORDER BY BYTES_SPILLED_TO_REMOTE_STORAGE DESC LIMIT 200');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_QUEUE_PRESSURE COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''hour'', START_TIME) AS HOUR_BUCKET, WAREHOUSE_NAME, COUNT_IF(QUEUED_OVERLOAD_TIME > 0) AS QUEUED_COUNT, AVG(QUEUED_OVERLOAD_TIME) AS AVG_QUEUE_MS, MAX(QUEUED_OVERLOAD_TIME) AS MAX_QUEUE_MS, SUM(QUEUED_OVERLOAD_TIME) AS TOTAL_QUEUE_MS FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE START_TIME >= ' || :since || ' GROUP BY 1, 2 HAVING QUEUED_COUNT > 0');
  END IF;

  IF (:sig:bi_layer::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_BI_QUERY_PRESSURE COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''hour'', q.START_TIME) AS HOUR_BUCKET, q.WAREHOUSE_NAME, s.CLIENT_APPLICATION_ID, CASE WHEN UPPER(s.CLIENT_APPLICATION_ID) LIKE ''%THOUGHTSPOT%'' THEN ''ThoughtSpot'' WHEN UPPER(s.CLIENT_APPLICATION_ID) LIKE ''%TABLEAU%'' THEN ''Tableau'' WHEN UPPER(s.CLIENT_APPLICATION_ID) LIKE ''%LOOKER%'' THEN ''Looker'' WHEN UPPER(s.CLIENT_APPLICATION_ID) LIKE ''%POWERBI%'' THEN ''PowerBI'' WHEN UPPER(s.CLIENT_APPLICATION_ID) LIKE ''%SIGMA%'' THEN ''Sigma'' ELSE ''Other'' END AS BI_TOOL, COUNT(*) AS QUERY_COUNT, AVG(q.TOTAL_ELAPSED_TIME) AS AVG_ELAPSED_MS, SUM(q.CREDITS_USED_CLOUD_SERVICES) AS CLOUD_CREDITS, COUNT_IF(q.BYTES_SPILLED_TO_REMOTE_STORAGE > 0) AS SPILL_COUNT FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY q JOIN SNOWFLAKE.ACCOUNT_USAGE.SESSIONS s ON q.SESSION_ID = s.SESSION_ID WHERE q.START_TIME >= ' || :since || ' AND s.CLIENT_APPLICATION_ID IS NOT NULL GROUP BY 1, 2, 3, 4');
  END IF;

  -- ── Views: Cost & Efficiency ───────────────────────────────────────────────
  IF (:sig:wh_credits::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_WAREHOUSE_CREDITS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT START_TIME, END_TIME, WAREHOUSE_NAME, CREDITS_USED, CREDITS_USED_COMPUTE, CREDITS_USED_CLOUD_SERVICES FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE START_TIME >= ' || :since);
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_CREDIT_TREND COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''day'', START_TIME) AS DAY_BUCKET, WAREHOUSE_NAME, SUM(CREDITS_USED) AS DAILY_CREDITS, SUM(CREDITS_USED_COMPUTE) AS DAILY_COMPUTE_CREDITS, SUM(CREDITS_USED_CLOUD_SERVICES) AS DAILY_CLOUD_CREDITS FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) GROUP BY 1, 2');
  END IF;

  IF (:sig:warehouse_churn::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_WAREHOUSE_CHURN COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''day'', TIMESTAMP) AS DAY_BUCKET, WAREHOUSE_NAME, COUNT_IF(EVENT_NAME = ''SUSPEND'') AS SUSPEND_COUNT, COUNT_IF(EVENT_NAME = ''RESUME'') AS RESUME_COUNT, COUNT_IF(EVENT_NAME = ''SUSPEND'') + COUNT_IF(EVENT_NAME = ''RESUME'') AS CHURN_EVENTS FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_EVENTS_HISTORY WHERE EVENT_NAME IN (''SUSPEND'', ''RESUME'') AND TIMESTAMP >= ' || :since || ' GROUP BY 1, 2');
  END IF;

  IF (:sig:access_history::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_UNUSED_TABLES COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS WITH recent_reads AS (SELECT f.VALUE:objectName::STRING AS OBJECT_FQN, MAX(ah.QUERY_START_TIME) AS LAST_READ_TIME FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY ah, TABLE(FLATTEN(ah.BASE_OBJECTS_ACCESSED)) f WHERE ah.QUERY_START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) AND f.VALUE:objectDomain::STRING = ''Table'' GROUP BY 1) SELECT t.TABLE_CATALOG AS DATABASE_NAME, t.TABLE_SCHEMA AS SCHEMA_NAME, t.TABLE_NAME, t.TABLE_TYPE, t.ROW_COUNT, t.BYTES, t.CREATED, t.LAST_ALTERED, rr.LAST_READ_TIME, DATEDIFF(''day'', rr.LAST_READ_TIME, CURRENT_TIMESTAMP()) AS DAYS_SINCE_LAST_READ FROM SNOWFLAKE.ACCOUNT_USAGE.TABLES t LEFT JOIN recent_reads rr ON rr.OBJECT_FQN = t.TABLE_CATALOG || ''.'' || t.TABLE_SCHEMA || ''.'' || t.TABLE_NAME WHERE t.DELETED IS NULL AND t.TABLE_TYPE = ''BASE TABLE'' AND t.BYTES > 0 AND (rr.LAST_READ_TIME IS NULL OR DATEDIFF(''day'', rr.LAST_READ_TIME, CURRENT_TIMESTAMP()) > 30)');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_ASSET_IMPORTANCE COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT f.VALUE:objectName::STRING AS OBJECT_FQN, SPLIT_PART(f.VALUE:objectName::STRING, ''.'', 1) AS DATABASE_NAME, SPLIT_PART(f.VALUE:objectName::STRING, ''.'', 2) AS SCHEMA_NAME, SPLIT_PART(f.VALUE:objectName::STRING, ''.'', 3) AS TABLE_NAME, COUNT(DISTINCT ah.QUERY_ID) AS READ_COUNT, COUNT(DISTINCT ah.USER_NAME) AS DISTINCT_CONSUMERS, MIN(ah.QUERY_START_TIME) AS FIRST_READ, MAX(ah.QUERY_START_TIME) AS LAST_READ FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY ah, TABLE(FLATTEN(ah.BASE_OBJECTS_ACCESSED)) f WHERE ah.QUERY_START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) AND f.VALUE:objectDomain::STRING = ''Table'' GROUP BY 1, 2, 3, 4');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_TABLE_IMPORTANCE COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT f.VALUE:objectName::STRING AS OBJECT_FQN, SPLIT_PART(f.VALUE:objectName::STRING, ''.'', 1) AS DATABASE_NAME, SPLIT_PART(f.VALUE:objectName::STRING, ''.'', 2) AS SCHEMA_NAME, SPLIT_PART(f.VALUE:objectName::STRING, ''.'', 3) AS TABLE_NAME, COUNT(DISTINCT ah.QUERY_ID) AS READ_COUNT_90D, COUNT(DISTINCT ah.USER_NAME) AS DISTINCT_CONSUMERS_90D, MAX(ah.QUERY_START_TIME) AS LAST_READ_TIME FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY ah, TABLE(FLATTEN(ah.BASE_OBJECTS_ACCESSED)) f WHERE ah.QUERY_START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) AND f.VALUE:objectDomain::STRING = ''Table'' GROUP BY 1, 2, 3, 4');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_MONITOR_GAPS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT imp.OBJECT_FQN, imp.DATABASE_NAME, imp.SCHEMA_NAME, imp.TABLE_NAME, imp.READ_COUNT_90D, imp.DISTINCT_CONSUMERS_90D, CASE WHEN dmf.TABLE_NAME IS NOT NULL THEN TRUE ELSE FALSE END AS HAS_DMF_ATTACHED FROM ' || :tgt || '.V_TABLE_IMPORTANCE imp LEFT JOIN (SELECT DISTINCT TABLE_DATABASE AS DATABASE_NAME, TABLE_SCHEMA AS SCHEMA_NAME, TABLE_NAME FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS WHERE MEASUREMENT_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP())) dmf ON dmf.DATABASE_NAME = imp.DATABASE_NAME AND dmf.SCHEMA_NAME = imp.SCHEMA_NAME AND dmf.TABLE_NAME = imp.TABLE_NAME WHERE dmf.TABLE_NAME IS NULL');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_RECOMMENDATIONS COMMENT = ''Derived from V_MONITOR_GAPS: read-heavy tables with no DMF attached, ranked, with the DDL that closes the gap. ESTIMATED_DAILY_COST assumes 2 DMFs at up to 24 evaluations/day and ~0.0009 credits per evaluation -- an estimate, not a measurement.'' AS
SELECT g.OBJECT_FQN, g.DATABASE_NAME, g.SCHEMA_NAME, g.TABLE_NAME,
       g.READ_COUNT_90D, g.DISTINCT_CONSUMERS_90D,
       g.HAS_DMF_ATTACHED AS HAS_DMF,
       ROUND(100 * PERCENT_RANK() OVER (ORDER BY g.READ_COUNT_90D + g.DISTINCT_CONSUMERS_90D * 10)) AS IMPORTANCE_SCORE,
       ''FRESHNESS, ROW_COUNT'' AS RECOMMENDED_DMFS,
       ''ALTER TABLE '' || g.OBJECT_FQN || '' SET DATA_METRIC_SCHEDULE = '' || CHR(39) || ''TRIGGER_ON_CHANGES'' || CHR(39) || ''; ALTER TABLE '' || g.OBJECT_FQN || '' ADD DATA METRIC FUNCTION SNOWFLAKE.CORE.ROW_COUNT ON ();'' AS DDL,
       ROUND(2 * 24 * 0.0009, 4) AS ESTIMATED_DAILY_COST
FROM ' || :tgt || '.V_MONITOR_GAPS g');
  END IF;

  -- ── Views: Data Quality ────────────────────────────────────────────────────
  IF (:sig:dmf_results::STRING = 'AVAILABLE' OR :sig:dmf_anomalies::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_DMF_RESULTS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT MEASUREMENT_TIME, TABLE_NAME, TABLE_SCHEMA AS SCHEMA_NAME, TABLE_DATABASE AS DATABASE_NAME, METRIC_NAME, VALUE, IS_ANOMALY, FORECAST, LOWER_BOUND, UPPER_BOUND FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS WHERE MEASUREMENT_TIME >= ' || :since);
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_DMF_ANOMALIES COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT MEASUREMENT_TIME, TABLE_NAME, TABLE_SCHEMA AS SCHEMA_NAME, TABLE_DATABASE AS DATABASE_NAME, METRIC_NAME, VALUE, IS_ANOMALY FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS WHERE IS_ANOMALY = TRUE AND MEASUREMENT_TIME >= ' || :since);
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_DQ_SCORECARD COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT TABLE_DATABASE AS DATABASE_NAME, TABLE_SCHEMA AS SCHEMA_NAME, TABLE_NAME, COUNT(DISTINCT METRIC_NAME) AS METRICS_ATTACHED, COUNT_IF(IS_ANOMALY = TRUE) AS ANOMALY_COUNT, COUNT_IF(IS_ANOMALY = FALSE) AS HEALTHY_COUNT, COUNT_IF(IS_ANOMALY IS NULL AND VALUE IS NOT NULL) AS BUILDING_BASELINE_COUNT, ROUND(DIV0(COUNT_IF(IS_ANOMALY = FALSE), NULLIF(COUNT_IF(IS_ANOMALY = FALSE) + COUNT_IF(IS_ANOMALY = TRUE), 0)) * 100, 2) AS HEALTH_SCORE_PCT FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS WHERE MEASUREMENT_TIME >= ' || :since || ' GROUP BY 1, 2, 3');
  END IF;

  -- ── Views: Alerts ──────────────────────────────────────────────────────────
  IF (:sig:alert_history::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_ALERT_HISTORY COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT SCHEDULED_TIME, COMPLETED_TIME, NAME AS ALERT_NAME, DATABASE_NAME, SCHEMA_NAME, STATE, CONDITION, CONDITION_QUERY_ID, ERROR_CODE, ERROR_MESSAGE, ACTION, ACTION_QUERY_ID FROM SNOWFLAKE.ACCOUNT_USAGE.ALERT_HISTORY WHERE SCHEDULED_TIME >= ' || :since);
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_ALERT_RELIABILITY COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''day'', SCHEDULED_TIME) AS DAY_BUCKET, NAME AS ALERT_NAME, DATABASE_NAME, SCHEMA_NAME, COUNT_IF(STATE = ''TRIGGERED'') AS TRIGGERED_COUNT, COUNT_IF(STATE = ''CONDITION_FALSE'') AS NOT_TRIGGERED_COUNT, COUNT_IF(STATE = ''CONDITION_FAILED'') AS CONDITION_FAILED_COUNT, COUNT_IF(STATE = ''ACTION_FAILED'') AS ACTION_FAILED_COUNT, COUNT(*) AS TOTAL_EVALUATIONS FROM SNOWFLAKE.ACCOUNT_USAGE.ALERT_HISTORY WHERE SCHEDULED_TIME >= ' || :since || ' GROUP BY 1, 2, 3, 4');
  END IF;

  -- ── Views: external monitoring footprint ────────────────────────────────────────────────────
  IF (:sig:ext_monitor_footprint::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_EXT_MONITOR_QUERY_FOOTPRINT COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT REGEXP_SUBSTR(QUERY_TAG, ''mc_monitor_id=([0-9a-f-]{36})'', 1, 1, ''i'', 1) AS EXT_MONITOR_ID, COUNT(*) AS QUERY_COUNT, SUM(TOTAL_ELAPSED_TIME) AS TOTAL_ELAPSED_MS, SUM(CREDITS_USED_CLOUD_SERVICES) AS ATTRIBUTABLE_CREDITS, COUNT_IF(QUERY_TYPE = ''SELECT'' AND ROWS_PRODUCED = 1) AS LIKELY_COUNT_QUERIES, MIN(START_TIME) AS FIRST_SEEN, MAX(START_TIME) AS LAST_SEEN FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE QUERY_TAG ILIKE ''%mc_monitor_id=%'' AND START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) GROUP BY 1');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_EXT_MONITOR_CREDIT_TREND COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''day'', START_TIME) AS DAY_BUCKET, COUNT(*) AS EXT_QUERY_COUNT, SUM(TOTAL_ELAPSED_TIME) AS TOTAL_ELAPSED_MS, SUM(CREDITS_USED_CLOUD_SERVICES) AS DAILY_EXT_CREDITS FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE QUERY_TAG ILIKE ''%mc_monitor_id=%'' AND START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) GROUP BY 1');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_EXT_MONITOR_BREAKDOWN COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT REGEXP_SUBSTR(QUERY_TAG, ''mc_monitor_id=([0-9a-f-]{36})'', 1, 1, ''i'', 1) AS EXT_MONITOR_ID, WAREHOUSE_NAME, COUNT(*) AS QUERY_COUNT, SUM(TOTAL_ELAPSED_TIME) AS TOTAL_ELAPSED_MS, SUM(CREDITS_USED_CLOUD_SERVICES) AS CREDITS_USED, COUNT_IF(QUERY_TYPE = ''SELECT'' AND ROWS_PRODUCED = 1) AS HOURLY_COUNT_QUERIES, AVG(TOTAL_ELAPSED_TIME) AS AVG_ELAPSED_MS FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE QUERY_TAG ILIKE ''%mc_monitor_id=%'' AND START_TIME >= DATEADD(day, -90, CURRENT_TIMESTAMP()) GROUP BY 1, 2');
  END IF;

  -- ── Views: Agent Observability (requires event table) ───────────────────────
  IF (:evt_table IS NOT NULL AND :sig:cortex_agents::STRING IN ('AVAILABLE', 'PARTIAL')) THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_AGENT_TRACES COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT TIMESTAMP AS EVENT_TIME, RESOURCE_ATTRIBUTES:"snow.database.name"::STRING AS DATABASE_NAME, RESOURCE_ATTRIBUTES:"snow.schema.name"::STRING AS SCHEMA_NAME, RESOURCE_ATTRIBUTES:"snow.executable.name"::STRING AS AGENT_NAME, RECORD_TYPE, RECORD:"severity_text"::STRING AS SEVERITY, RECORD_ATTRIBUTES:"cortex.complete.model"::STRING AS MODEL_USED, RECORD_ATTRIBUTES:"cortex.complete.usage.input_tokens"::NUMBER AS INPUT_TOKENS, RECORD_ATTRIBUTES:"cortex.complete.usage.output_tokens"::NUMBER AS OUTPUT_TOKENS FROM ' || :evt_table || ' WHERE RECORD_TYPE = ''SPAN'' AND RESOURCE_ATTRIBUTES:"snow.executable.type"::STRING = ''AGENT'' AND TIMESTAMP >= ' || :since);
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_AGENT_LATENCY COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT DATE_TRUNC(''hour'', TIMESTAMP) AS HOUR_BUCKET, RESOURCE_ATTRIBUTES:"snow.executable.name"::STRING AS AGENT_NAME, COUNT(*) AS REQUEST_COUNT, AVG(RECORD_ATTRIBUTES:"duration_ms"::NUMBER) AS AVG_LATENCY_MS, MAX(RECORD_ATTRIBUTES:"duration_ms"::NUMBER) AS MAX_LATENCY_MS, PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY RECORD_ATTRIBUTES:"duration_ms"::NUMBER) AS P95_LATENCY_MS FROM ' || :evt_table || ' WHERE RECORD_TYPE = ''SPAN'' AND RESOURCE_ATTRIBUTES:"snow.executable.type"::STRING = ''AGENT'' AND TIMESTAMP >= ' || :since || ' GROUP BY 1, 2');
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_AGENT_ERRORS COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT TIMESTAMP AS EVENT_TIME, RESOURCE_ATTRIBUTES:"snow.executable.name"::STRING AS AGENT_NAME, RESOURCE_ATTRIBUTES:"snow.database.name"::STRING AS DATABASE_NAME, RESOURCE_ATTRIBUTES:"snow.schema.name"::STRING AS SCHEMA_NAME, RECORD:"severity_text"::STRING AS SEVERITY, VALUE::STRING AS ERROR_MESSAGE FROM ' || :evt_table || ' WHERE RECORD_TYPE IN (''LOG'', ''SPAN'') AND RESOURCE_ATTRIBUTES:"snow.executable.type"::STRING = ''AGENT'' AND RECORD:"severity_text"::STRING IN (''ERROR'', ''FATAL'', ''WARN'') AND TIMESTAMP >= ' || :since);
  END IF;

  -- Monitor Coverage view (always built)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_MONITOR_COVERAGE COMMENT = ''ACCOUNT_USAGE-sourced: 45min-3hr lag'' AS SELECT ''task_runs'' AS SIGNAL_NAME, CASE WHEN COUNT(*) > 0 THEN ''AVAILABLE'' ELSE ''EMPTY'' END AS STATUS, COUNT(*) AS ROW_COUNT FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE SCHEDULED_TIME >= ' || :since || ' UNION ALL SELECT ''dynamic_table_refreshes'', CASE WHEN COUNT(*) > 0 THEN ''AVAILABLE'' ELSE ''EMPTY'' END, COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.DYNAMIC_TABLE_REFRESH_HISTORY WHERE REFRESH_START_TIME >= ' || :since || ' UNION ALL SELECT ''copy_loads'', CASE WHEN COUNT(*) > 0 THEN ''AVAILABLE'' ELSE ''EMPTY'' END, COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.COPY_HISTORY WHERE LAST_LOAD_TIME >= ' || :since || ' UNION ALL SELECT ''wh_credits'', CASE WHEN COUNT(*) > 0 THEN ''AVAILABLE'' ELSE ''EMPTY'' END, COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE START_TIME >= ' || :since || ' UNION ALL SELECT ''ext_monitor_footprint'', CASE WHEN COUNT(*) > 0 THEN ''AVAILABLE'' ELSE ''EMPTY'' END, COUNT(*) FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE QUERY_TAG ILIKE ''%mc_monitor_id=%'' AND START_TIME >= ' || :since);

  -- ── Incident lifecycle objects ─────────────────────────────────────────────
  stmts := ARRAY_APPEND(:stmts, 'CREATE TABLE IF NOT EXISTS ' || :tgt || '.INCIDENTS (INCIDENT_ID NUMBER AUTOINCREMENT PRIMARY KEY, FINGERPRINT VARCHAR(64) NOT NULL, SIGNAL_TYPE VARCHAR(100) NOT NULL, OBJECT_FQN VARCHAR(512) NOT NULL, METRIC_NAME VARCHAR(256), SEVERITY VARCHAR(20) DEFAULT ''MEDIUM'', STATUS VARCHAR(20) DEFAULT ''OPEN'', OWNER VARCHAR(256), DETECTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), ACKNOWLEDGED_AT TIMESTAMP_NTZ, RESOLVED_AT TIMESTAMP_NTZ, GROUP_ID NUMBER, IS_ROOT BOOLEAN DEFAULT FALSE, OCCURRENCE_COUNT NUMBER DEFAULT 1, LAST_SEEN_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), REGRESSED BOOLEAN DEFAULT FALSE, ROOT_CAUSE_NOTE VARCHAR(4000), AI_SUMMARY VARCHAR(4000), CONSTRAINT UQ_FINGERPRINT UNIQUE (FINGERPRINT))');
  stmts := ARRAY_APPEND(:stmts, 'CREATE TABLE IF NOT EXISTS ' || :tgt || '.INCIDENT_EVENTS (EVENT_ID NUMBER AUTOINCREMENT PRIMARY KEY, INCIDENT_ID NUMBER NOT NULL, EVENT_TYPE VARCHAR(50) NOT NULL, FROM_STATUS VARCHAR(20), TO_STATUS VARCHAR(20), ACTOR VARCHAR(256) DEFAULT CURRENT_USER(), EVENT_TIME TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), DETAIL VARCHAR(4000))');
  stmts := ARRAY_APPEND(:stmts, 'CREATE TABLE IF NOT EXISTS ' || :tgt || '.SLO_POLICY (SEVERITY VARCHAR(20) PRIMARY KEY, TARGET_ACK_MINUTES NUMBER NOT NULL, TARGET_RESOLVE_MINUTES NUMBER NOT NULL)');
  stmts := ARRAY_APPEND(:stmts, 'MERGE INTO ' || :tgt || '.SLO_POLICY AS tgt USING (SELECT * FROM VALUES (''CRITICAL'', 15, 60), (''HIGH'', 30, 240), (''MEDIUM'', 120, 1440), (''LOW'', 480, 4320) AS v(SEVERITY, TARGET_ACK_MINUTES, TARGET_RESOLVE_MINUTES)) AS src ON tgt.SEVERITY = src.SEVERITY WHEN NOT MATCHED THEN INSERT VALUES (src.SEVERITY, src.TARGET_ACK_MINUTES, src.TARGET_RESOLVE_MINUTES)');

  -- RECORD_INCIDENT procedure (with auto-triage and auto-notify)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.RECORD_INCIDENT(P_SIGNAL_TYPE VARCHAR, P_OBJECT_FQN VARCHAR, P_METRIC_NAME VARCHAR, P_SEVERITY VARCHAR) RETURNS VARCHAR LANGUAGE SQL AS DECLARE fp VARCHAR; v_incident_id NUMBER; v_is_new BOOLEAN DEFAULT FALSE; v_is_regressed BOOLEAN DEFAULT FALSE; BEGIN fp := SHA2(:P_SIGNAL_TYPE || :P_OBJECT_FQN || COALESCE(:P_METRIC_NAME, ''''), 256); MERGE INTO ' || :tgt || '.INCIDENTS AS tgt USING (SELECT :fp AS FP) AS src ON tgt.FINGERPRINT = src.FP WHEN MATCHED THEN UPDATE SET OCCURRENCE_COUNT = tgt.OCCURRENCE_COUNT + 1, LAST_SEEN_AT = CURRENT_TIMESTAMP(), REGRESSED = IFF(tgt.STATUS = ''RESOLVED'', TRUE, tgt.REGRESSED), STATUS = IFF(tgt.STATUS = ''RESOLVED'', ''OPEN'', tgt.STATUS) WHEN NOT MATCHED THEN INSERT (FINGERPRINT, SIGNAL_TYPE, OBJECT_FQN, METRIC_NAME, SEVERITY) VALUES (:fp, :P_SIGNAL_TYPE, :P_OBJECT_FQN, :P_METRIC_NAME, :P_SEVERITY); SELECT INCIDENT_ID INTO v_incident_id FROM ' || :tgt || '.INCIDENTS WHERE FINGERPRINT = :fp; v_is_new := (SELECT OCCURRENCE_COUNT = 1 FROM ' || :tgt || '.INCIDENTS WHERE INCIDENT_ID = :v_incident_id); v_is_regressed := (SELECT REGRESSED = TRUE AND STATUS = ''OPEN'' AND OCCURRENCE_COUNT > 1 FROM ' || :tgt || '.INCIDENTS WHERE INCIDENT_ID = :v_incident_id); INSERT INTO ' || :tgt || '.INCIDENT_EVENTS (INCIDENT_ID, EVENT_TYPE, TO_STATUS, DETAIL) SELECT INCIDENT_ID, IFF(OCCURRENCE_COUNT = 1, ''CREATED'', IFF(REGRESSED = TRUE AND STATUS = ''OPEN'', ''REGRESSED'', ''RECURRENCE'')), STATUS, ''Signal: '' || :P_SIGNAL_TYPE || '' Object: '' || :P_OBJECT_FQN FROM ' || :tgt || '.INCIDENTS WHERE FINGERPRINT = :fp; IF (:v_is_new OR :v_is_regressed) THEN BEGIN CALL ' || :tgt || '.TRIAGE_INCIDENT(:v_incident_id); EXCEPTION WHEN OTHER THEN LET fsev VARCHAR := CASE WHEN :P_SIGNAL_TYPE IN (''task_failure'',''pipeline_failure'') THEN ''HIGH'' WHEN :P_SIGNAL_TYPE IN (''dmf_anomaly'',''freshness_violation'') THEN ''MEDIUM'' ELSE COALESCE(:P_SEVERITY, ''MEDIUM'') END; UPDATE ' || :tgt || '.INCIDENTS SET SEVERITY = :fsev WHERE INCIDENT_ID = :v_incident_id; INSERT INTO ' || :tgt || '.INCIDENT_EVENTS (INCIDENT_ID, EVENT_TYPE, DETAIL) VALUES (:v_incident_id, ''TRIAGE_FALLBACK'', ''Deterministic: severity='' || :fsev); END; BEGIN CALL ' || :tgt || '.SEND_INCIDENT_NOTIFICATION(:v_incident_id); EXCEPTION WHEN OTHER THEN NULL; END; END IF; RETURN ''recorded''; END');

  -- V_SLO_COMPLIANCE view (incident response SLO attainment)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_SLO_COMPLIANCE COMMENT = ''Incident SLO attainment'' AS SELECT i.INCIDENT_ID, i.FINGERPRINT, i.SIGNAL_TYPE, i.OBJECT_FQN, i.SEVERITY, i.STATUS, i.DETECTED_AT, i.ACKNOWLEDGED_AT, i.RESOLVED_AT, p.TARGET_ACK_MINUTES, p.TARGET_RESOLVE_MINUTES, TIMESTAMPDIFF(MINUTE, i.DETECTED_AT, COALESCE(i.ACKNOWLEDGED_AT, CURRENT_TIMESTAMP())) AS ACTUAL_ACK_MINUTES, TIMESTAMPDIFF(MINUTE, i.DETECTED_AT, COALESCE(i.RESOLVED_AT, CURRENT_TIMESTAMP())) AS ACTUAL_RESOLVE_MINUTES, CASE WHEN i.ACKNOWLEDGED_AT IS NOT NULL AND TIMESTAMPDIFF(MINUTE, i.DETECTED_AT, i.ACKNOWLEDGED_AT) <= p.TARGET_ACK_MINUTES THEN TRUE WHEN i.ACKNOWLEDGED_AT IS NULL AND TIMESTAMPDIFF(MINUTE, i.DETECTED_AT, CURRENT_TIMESTAMP()) <= p.TARGET_ACK_MINUTES THEN NULL ELSE FALSE END AS ACK_SLO_MET, CASE WHEN i.RESOLVED_AT IS NOT NULL AND TIMESTAMPDIFF(MINUTE, i.DETECTED_AT, i.RESOLVED_AT) <= p.TARGET_RESOLVE_MINUTES THEN TRUE WHEN i.RESOLVED_AT IS NULL AND TIMESTAMPDIFF(MINUTE, i.DETECTED_AT, CURRENT_TIMESTAMP()) <= p.TARGET_RESOLVE_MINUTES THEN NULL ELSE FALSE END AS RESOLVE_SLO_MET FROM ' || :tgt || '.INCIDENTS i LEFT JOIN ' || :tgt || '.SLO_POLICY p ON i.SEVERITY = p.SEVERITY');

  -- TRANSITION_INCIDENT procedure (core incident lifecycle — unconditional)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.TRANSITION_INCIDENT(P_INCIDENT_ID NUMBER, P_TO_STATUS VARCHAR, P_ACTOR VARCHAR, P_DETAIL VARCHAR) RETURNS VARCHAR LANGUAGE SQL AS DECLARE cur_st VARCHAR; allowed BOOLEAN DEFAULT FALSE; BEGIN cur_st := (SELECT STATUS FROM ' || :tgt || '.INCIDENTS WHERE INCIDENT_ID = :P_INCIDENT_ID); IF (:cur_st IS NULL) THEN RETURN ''error: incident not found''; END IF; CASE WHEN :cur_st = ''OPEN'' AND :P_TO_STATUS IN (''ACKNOWLEDGED'',''MUTED'') THEN allowed := TRUE; WHEN :cur_st = ''ACKNOWLEDGED'' AND :P_TO_STATUS IN (''INVESTIGATING'',''RESOLVED'',''MUTED'') THEN allowed := TRUE; WHEN :cur_st = ''INVESTIGATING'' AND :P_TO_STATUS IN (''RESOLVED'',''MUTED'') THEN allowed := TRUE; WHEN :cur_st = ''MUTED'' AND :P_TO_STATUS = ''OPEN'' THEN allowed := TRUE; ELSE allowed := FALSE; END CASE; IF (NOT :allowed) THEN RETURN ''error: invalid transition from '' || :cur_st || '' to '' || :P_TO_STATUS; END IF; UPDATE ' || :tgt || '.INCIDENTS SET STATUS = :P_TO_STATUS, ACKNOWLEDGED_AT = CASE WHEN :P_TO_STATUS = ''ACKNOWLEDGED'' AND ACKNOWLEDGED_AT IS NULL THEN CURRENT_TIMESTAMP() ELSE ACKNOWLEDGED_AT END, RESOLVED_AT = CASE WHEN :P_TO_STATUS = ''RESOLVED'' THEN CURRENT_TIMESTAMP() ELSE RESOLVED_AT END WHERE INCIDENT_ID = :P_INCIDENT_ID; INSERT INTO ' || :tgt || '.INCIDENT_EVENTS (INCIDENT_ID, EVENT_TYPE, FROM_STATUS, TO_STATUS, ACTOR, DETAIL) VALUES (:P_INCIDENT_ID, ''TRANSITION'', :cur_st, :P_TO_STATUS, :P_ACTOR, :P_DETAIL); RETURN ''ok''; END');

  -- GROUP_INCIDENTS procedure (lineage-aware correlation with IS_ROOT — unconditional)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.GROUP_INCIDENTS(P_WINDOW_MINUTES NUMBER DEFAULT 60, P_MAX_HOPS NUMBER DEFAULT 3) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_grouped NUMBER DEFAULT 0; v_next_gid NUMBER; cur CURSOR FOR SELECT INCIDENT_ID, OBJECT_FQN FROM ' || :tgt || '.INCIDENTS WHERE STATUS IN (''OPEN'',''ACKNOWLEDGED'',''INVESTIGATING'') AND GROUP_ID IS NULL AND DETECTED_AT >= DATEADD(MINUTE, -1 * :P_WINDOW_MINUTES, CURRENT_TIMESTAMP()); BEGIN v_next_gid := (SELECT COALESCE(MAX(GROUP_ID), 0) + 1 FROM ' || :tgt || '.INCIDENTS); FOR rec IN cur DO LET v_fqn VARCHAR := rec.OBJECT_FQN; LET v_id NUMBER := rec.INCIDENT_ID; BEGIN UPDATE ' || :tgt || '.INCIDENTS dest SET GROUP_ID = :v_next_gid WHERE dest.INCIDENT_ID != :v_id AND dest.STATUS IN (''OPEN'',''ACKNOWLEDGED'',''INVESTIGATING'') AND dest.GROUP_ID IS NULL AND dest.DETECTED_AT >= DATEADD(MINUTE, -1 * :P_WINDOW_MINUTES, CURRENT_TIMESTAMP()) AND dest.OBJECT_FQN IN (SELECT DISTINCT TARGET_OBJECT_DATABASE || ''.'' || TARGET_OBJECT_SCHEMA || ''.'' || TARGET_OBJECT_NAME FROM TABLE(SNOWFLAKE.CORE.GET_LINEAGE(:v_fqn, ''TABLE'', '''', :P_MAX_HOPS, ''downstream'')) UNION SELECT DISTINCT SOURCE_OBJECT_DATABASE || ''.'' || SOURCE_OBJECT_SCHEMA || ''.'' || SOURCE_OBJECT_NAME FROM TABLE(SNOWFLAKE.CORE.GET_LINEAGE(:v_fqn, ''TABLE'', '''', :P_MAX_HOPS, ''upstream''))); IF ((SELECT COUNT(*) FROM ' || :tgt || '.INCIDENTS WHERE GROUP_ID = :v_next_gid) > 0) THEN UPDATE ' || :tgt || '.INCIDENTS SET GROUP_ID = :v_next_gid WHERE INCIDENT_ID = :v_id; v_grouped := :v_grouped + 1; UPDATE ' || :tgt || '.INCIDENTS SET IS_ROOT = FALSE WHERE GROUP_ID = :v_next_gid; UPDATE ' || :tgt || '.INCIDENTS SET IS_ROOT = TRUE WHERE GROUP_ID = :v_next_gid AND OBJECT_FQN NOT IN (SELECT DISTINCT TARGET_OBJECT_DATABASE || ''.'' || TARGET_OBJECT_SCHEMA || ''.'' || TARGET_OBJECT_NAME FROM ' || :tgt || '.INCIDENTS src_inc, TABLE(SNOWFLAKE.CORE.GET_LINEAGE(src_inc.OBJECT_FQN, ''TABLE'', '''', :P_MAX_HOPS, ''downstream'')) lin WHERE src_inc.GROUP_ID = :v_next_gid); IF ((SELECT COUNT(*) FROM ' || :tgt || '.INCIDENTS WHERE GROUP_ID = :v_next_gid AND IS_ROOT = TRUE) = 0) THEN UPDATE ' || :tgt || '.INCIDENTS SET IS_ROOT = TRUE WHERE INCIDENT_ID = (SELECT INCIDENT_ID FROM ' || :tgt || '.INCIDENTS WHERE GROUP_ID = :v_next_gid ORDER BY DETECTED_AT ASC LIMIT 1); END IF; v_next_gid := :v_next_gid + 1; END IF; EXCEPTION WHEN OTHER THEN NULL; END; END FOR; RETURN ''groups_created='' || :v_grouped; END');

  -- SEND_INCIDENT_NOTIFICATION procedure (Block Kit payload — unconditional)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.SEND_INCIDENT_NOTIFICATION(P_INCIDENT_ID NUMBER) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_fqn VARCHAR; v_signal VARCHAR; v_severity VARCHAR; v_occ NUMBER; v_group_id NUMBER; v_owner VARCHAR; v_detected_at TIMESTAMP_NTZ; v_downstream NUMBER DEFAULT 0; v_group_size NUMBER DEFAULT 0; v_payload VARCHAR; v_notif VARCHAR; BEGIN SELECT OBJECT_FQN, SIGNAL_TYPE, SEVERITY, OCCURRENCE_COUNT, GROUP_ID, OWNER, DETECTED_AT INTO v_fqn, v_signal, v_severity, v_occ, v_group_id, v_owner, v_detected_at FROM ' || :tgt || '.INCIDENTS WHERE INCIDENT_ID = :P_INCIDENT_ID; IF (:v_fqn IS NULL) THEN RETURN ''error: not found''; END IF; BEGIN v_notif := (SELECT NULLIF(GETVARIABLE(''MONITOR_NOTIFICATION_INTEGRATION''), '''')); EXCEPTION WHEN OTHER THEN v_notif := NULL; END; BEGIN SELECT COUNT(DISTINCT TARGET_OBJECT_NAME) INTO v_downstream FROM TABLE(SNOWFLAKE.CORE.GET_LINEAGE(:v_fqn, ''TABLE'', '''', 3, ''downstream'')); EXCEPTION WHEN OTHER THEN v_downstream := 0; END; IF (:v_group_id IS NOT NULL) THEN BEGIN SELECT COUNT(*) INTO v_group_size FROM ' || :tgt || '.INCIDENTS WHERE GROUP_ID = :v_group_id; EXCEPTION WHEN OTHER THEN v_group_size := 0; END; END IF; v_payload := OBJECT_CONSTRUCT(''blocks'', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(''type'', ''header'', ''text'', OBJECT_CONSTRUCT(''type'', ''plain_text'', ''text'', IFF(:v_severity = ''CRITICAL'', '':rotating_light:'', '':warning:'') || '' Data Incident: '' || :v_severity || '' — '' || :v_signal)), OBJECT_CONSTRUCT(''type'', ''section'', ''fields'', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(''type'', ''mrkdwn'', ''text'', ''*Object:*\\n'' || :v_fqn), OBJECT_CONSTRUCT(''type'', ''mrkdwn'', ''text'', ''*Severity:*\\n'' || :v_severity), OBJECT_CONSTRUCT(''type'', ''mrkdwn'', ''text'', ''*Signal:*\\n'' || :v_signal), OBJECT_CONSTRUCT(''type'', ''mrkdwn'', ''text'', ''*Occurrences:*\\n'' || :v_occ::VARCHAR))), OBJECT_CONSTRUCT(''type'', ''context'', ''elements'', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(''type'', ''mrkdwn'', ''text'', ''Blast radius: '' || :v_downstream::VARCHAR || '' downstream | '' || IFF(:v_group_id IS NOT NULL, ''Group #'' || :v_group_id::VARCHAR || '' ('' || :v_group_size::VARCHAR || '' related) | '', '''') || ''Owner: '' || COALESCE(:v_owner, ''unassigned'')))), OBJECT_CONSTRUCT(''type'', ''actions'', ''elements'', ARRAY_CONSTRUCT(OBJECT_CONSTRUCT(''type'', ''button'', ''text'', OBJECT_CONSTRUCT(''type'', ''plain_text'', ''text'', ''View Incident''), ''url'', ''?incident_id='' || :P_INCIDENT_ID::VARCHAR, ''action_id'', ''view_'' || :P_INCIDENT_ID::VARCHAR)))))::VARCHAR; IF (:v_notif IS NOT NULL) THEN CALL SYSTEM$SEND_SNOWFLAKE_NOTIFICATION(:v_notif, :v_payload); END IF; RETURN :v_payload; END');

  -- V_INCIDENT_GROUPS view (one row per group with root and member count — unconditional)
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_INCIDENT_GROUPS COMMENT = ''Incident group summary with root cause identification. NOTE: lineage grouping does NOT catch correlated-but-not-lineage-linked failures.'' AS SELECT g.GROUP_ID, g.MEMBER_COUNT, g.EARLIEST_DETECTED, g.LATEST_DETECTED, TIMESTAMPDIFF(MINUTE, g.EARLIEST_DETECTED, g.LATEST_DETECTED) AS SPAN_MINUTES, r.INCIDENT_ID AS ROOT_INCIDENT_ID, r.OBJECT_FQN AS ROOT_OBJECT_FQN, r.SIGNAL_TYPE AS ROOT_SIGNAL_TYPE, r.SEVERITY AS GROUP_SEVERITY, r.AI_SUMMARY AS ROOT_SUMMARY FROM (SELECT GROUP_ID, COUNT(*) AS MEMBER_COUNT, MIN(DETECTED_AT) AS EARLIEST_DETECTED, MAX(DETECTED_AT) AS LATEST_DETECTED FROM ' || :tgt || '.INCIDENTS WHERE GROUP_ID IS NOT NULL GROUP BY GROUP_ID) g LEFT JOIN ' || :tgt || '.INCIDENTS r ON r.GROUP_ID = g.GROUP_ID AND r.IS_ROOT = TRUE');

  -- ── Contract objects (MONITOR_CONFIG, CONTRACT_BREACH, CHECK_CONTRACTS, RECONCILE_MONITORS) ──
  stmts := ARRAY_APPEND(:stmts, 'CREATE TABLE IF NOT EXISTS ' || :tgt || '.MONITOR_CONFIG (CONFIG_ID NUMBER AUTOINCREMENT PRIMARY KEY, OBJECT_FQN VARCHAR NOT NULL, METRIC_NAME VARCHAR NOT NULL, DMF_NAME VARCHAR NOT NULL, EXPECTED_SCHEDULE VARCHAR DEFAULT ''TRIGGER_ON_CHANGES'', THRESHOLD FLOAT NOT NULL, THRESHOLD_DIRECTION VARCHAR DEFAULT ''ABOVE'', DQ_DIMENSION VARCHAR NOT NULL CHECK (DQ_DIMENSION IN (''Accuracy'',''Completeness'',''Consistency'',''Timeliness'',''Validity'',''Uniqueness'')), ENABLED BOOLEAN DEFAULT TRUE, CREATED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), UPDATED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), CONSTRAINT uq_config UNIQUE (OBJECT_FQN, METRIC_NAME))');

  -- V_FRESHNESS_SLA joins MONITOR_CONFIG, so it can only be appended once that
  -- table is in the statement list. Same guard as V_TABLE_FRESHNESS, which it reads.
  IF (:sig:table_dml::STRING = 'AVAILABLE') THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE VIEW ' || :tgt || '.V_FRESHNESS_SLA COMMENT = ''Derived from V_TABLE_FRESHNESS. SLA_HOURS comes from the Timeliness thresholds in MONITOR_CONFIG where one is configured, else a 24h default.'' AS
SELECT f.DATABASE_NAME, f.SCHEMA_NAME, f.TABLE_NAME,
       f.DATABASE_NAME || ''.'' || f.SCHEMA_NAME || ''.'' || f.TABLE_NAME AS OBJECT_FQN,
       f.LAST_DML_TIME AS LAST_DML,
       ROUND(f.MINUTES_SINCE_LAST_DML / 60.0, 2) AS HOURS_SINCE_DML,
       COALESCE(c.SLA_HOURS, 24) AS SLA_HOURS,
       CASE WHEN f.MINUTES_SINCE_LAST_DML / 60.0 > COALESCE(c.SLA_HOURS, 24) THEN ''BREACH''
            WHEN f.MINUTES_SINCE_LAST_DML / 60.0 > COALESCE(c.SLA_HOURS, 24) * 0.75 THEN ''WARNING''
            ELSE ''OK'' END AS STATUS
FROM ' || :tgt || '.V_TABLE_FRESHNESS f
LEFT JOIN (SELECT OBJECT_FQN, MIN(THRESHOLD) AS SLA_HOURS FROM ' || :tgt || '.MONITOR_CONFIG
           WHERE DQ_DIMENSION = ''Timeliness'' AND ENABLED GROUP BY OBJECT_FQN) c
  ON c.OBJECT_FQN = f.DATABASE_NAME || ''.'' || f.SCHEMA_NAME || ''.'' || f.TABLE_NAME');
  END IF;
  stmts := ARRAY_APPEND(:stmts, 'CREATE TABLE IF NOT EXISTS ' || :tgt || '.CONTRACT_BREACH (BREACH_ID NUMBER AUTOINCREMENT PRIMARY KEY, CONFIG_ID NUMBER NOT NULL, OBJECT_FQN VARCHAR NOT NULL, METRIC_NAME VARCHAR NOT NULL, DQ_DIMENSION VARCHAR NOT NULL, THRESHOLD FLOAT NOT NULL, ACTUAL_VALUE FLOAT NOT NULL, THRESHOLD_DIRECTION VARCHAR NOT NULL, BREACH_DETECTED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(), CHECK_SCOPE VARCHAR, RESOLVED_AT TIMESTAMP_NTZ)');
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.CHECK_CONTRACTS(P_SCOPE VARCHAR) RETURNS VARIANT LANGUAGE SQL EXECUTE AS CALLER AS DECLARE violations ARRAY := ARRAY_CONSTRUCT(); checked INT := 0; violated INT := 0; cur CURSOR FOR SELECT c.CONFIG_ID, c.OBJECT_FQN, c.METRIC_NAME, c.DMF_NAME, c.THRESHOLD, c.THRESHOLD_DIRECTION, c.DQ_DIMENSION, r.LATEST_VALUE, r.MEASUREMENT_TIME FROM ' || :tgt || '.MONITOR_CONFIG c LEFT JOIN (SELECT TABLE_DATABASE || ''.'' || TABLE_SCHEMA || ''.'' || TABLE_NAME AS OBJ_FQN, METRIC_DATABASE || ''.'' || METRIC_SCHEMA || ''.'' || METRIC_NAME AS DMF_FQN, VALUE::FLOAT AS LATEST_VALUE, MEASUREMENT_TIME, ROW_NUMBER() OVER (PARTITION BY TABLE_DATABASE, TABLE_SCHEMA, TABLE_NAME, METRIC_DATABASE, METRIC_SCHEMA, METRIC_NAME ORDER BY MEASUREMENT_TIME DESC) AS RN FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS) r ON r.OBJ_FQN = c.OBJECT_FQN AND r.DMF_FQN = c.DMF_NAME AND r.RN = 1 WHERE c.ENABLED = TRUE AND c.OBJECT_FQN LIKE :P_SCOPE; BEGIN FOR rec IN cur DO checked := :checked + 1; LET is_breach BOOLEAN := FALSE; IF (rec.LATEST_VALUE IS NOT NULL) THEN IF (rec.THRESHOLD_DIRECTION = ''ABOVE'' AND rec.LATEST_VALUE > rec.THRESHOLD) THEN is_breach := TRUE; ELSEIF (rec.THRESHOLD_DIRECTION = ''BELOW'' AND rec.LATEST_VALUE < rec.THRESHOLD) THEN is_breach := TRUE; END IF; END IF; IF (:is_breach) THEN violated := :violated + 1; violations := ARRAY_APPEND(:violations, OBJECT_CONSTRUCT(''config_id'', rec.CONFIG_ID, ''object_fqn'', rec.OBJECT_FQN, ''metric_name'', rec.METRIC_NAME, ''dq_dimension'', rec.DQ_DIMENSION, ''threshold'', rec.THRESHOLD, ''threshold_direction'', rec.THRESHOLD_DIRECTION, ''actual_value'', rec.LATEST_VALUE, ''measured_at'', rec.MEASUREMENT_TIME::VARCHAR)); INSERT INTO ' || :tgt || '.CONTRACT_BREACH (CONFIG_ID, OBJECT_FQN, METRIC_NAME, DQ_DIMENSION, THRESHOLD, ACTUAL_VALUE, THRESHOLD_DIRECTION, CHECK_SCOPE) VALUES (rec.CONFIG_ID, rec.OBJECT_FQN, rec.METRIC_NAME, rec.DQ_DIMENSION, rec.THRESHOLD, rec.LATEST_VALUE, rec.THRESHOLD_DIRECTION, :P_SCOPE); END IF; END FOR; RETURN OBJECT_CONSTRUCT(''overall_status'', IFF(:violated > 0, ''FAIL'', ''PASS''), ''violation_count'', :violated, ''checked_count'', :checked, ''violations'', :violations); END');
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.RECONCILE_MONITORS() RETURNS VARIANT LANGUAGE SQL EXECUTE AS CALLER AS DECLARE findings ARRAY := ARRAY_CONSTRUCT(); missing_count INT := 0; extra_count INT := 0; drifted_count INT := 0; cur_missing CURSOR FOR SELECT d.OBJECT_FQN, d.DMF_NAME, d.EXPECTED_SCHEDULE FROM ' || :tgt || '.MONITOR_CONFIG d WHERE d.ENABLED = TRUE AND NOT EXISTS (SELECT 1 FROM TABLE(INFORMATION_SCHEMA.DATA_METRIC_FUNCTION_REFERENCES(REF_ENTITY_NAME => d.OBJECT_FQN, REF_ENTITY_DOMAIN => ''TABLE'')) r WHERE r.METRIC_DATABASE || ''.'' || r.METRIC_SCHEMA || ''.'' || r.METRIC_NAME = d.DMF_NAME); BEGIN FOR rec IN cur_missing DO missing_count := :missing_count + 1; findings := ARRAY_APPEND(:findings, OBJECT_CONSTRUCT(''status'', ''MISSING'', ''object_fqn'', rec.OBJECT_FQN, ''dmf_name'', rec.DMF_NAME, ''expected_schedule'', rec.EXPECTED_SCHEDULE)); END FOR; RETURN OBJECT_CONSTRUCT(''missing_count'', :missing_count, ''extra_count'', :extra_count, ''drifted_count'', :drifted_count, ''total_findings'', :missing_count + :extra_count + :drifted_count, ''findings'', :findings); END');

  -- ── Agent procedures (gated on MONITOR_AGENTS) ──────────────────────────────
  IF (COALESCE(:do_agents, FALSE)) THEN
    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.TRIAGE_INCIDENT(P_INCIDENT_ID NUMBER) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_fqn VARCHAR; v_signal VARCHAR; v_metric VARCHAR; v_reads NUMBER DEFAULT 0; v_downstream NUMBER DEFAULT 0; v_severity VARCHAR; v_owner VARCHAR; v_summary VARCHAR; v_evidence VARCHAR; BEGIN SELECT OBJECT_FQN, SIGNAL_TYPE, METRIC_NAME INTO v_fqn, v_signal, v_metric FROM ' || :tgt || '.INCIDENTS WHERE INCIDENT_ID = :P_INCIDENT_ID; IF (:v_fqn IS NULL) THEN RETURN ''error: not found''; END IF; BEGIN SELECT COUNT(DISTINCT QUERY_ID) INTO v_reads FROM SNOWFLAKE.ACCOUNT_USAGE.ACCESS_HISTORY, LATERAL FLATTEN(input => BASE_OBJECTS_ACCESSED) f WHERE f.value:objectName::VARCHAR = :v_fqn AND QUERY_START_TIME >= DATEADD(DAY, -30, CURRENT_TIMESTAMP()); EXCEPTION WHEN OTHER THEN v_reads := 0; END; BEGIN SELECT COUNT(DISTINCT TARGET_OBJECT_NAME) INTO v_downstream FROM TABLE(SNOWFLAKE.CORE.GET_LINEAGE(:v_fqn, ''TABLE'', '''', 3, ''downstream'')); EXCEPTION WHEN OTHER THEN v_downstream := 0; END; v_severity := CASE WHEN :v_reads > 100 AND :v_downstream > 5 THEN ''CRITICAL'' WHEN :v_reads > 50 OR :v_downstream > 3 THEN ''HIGH'' WHEN :v_reads > 10 OR :v_downstream > 1 THEN ''MEDIUM'' ELSE ''LOW'' END; BEGIN SELECT GRANTEE INTO v_owner FROM SNOWFLAKE.ACCOUNT_USAGE.GRANTS_TO_ROLES WHERE NAME = SPLIT_PART(:v_fqn, ''.'', 3) AND TABLE_SCHEMA = SPLIT_PART(:v_fqn, ''.'', 2) AND TABLE_CATALOG = SPLIT_PART(:v_fqn, ''.'', 1) AND PRIVILEGE = ''OWNERSHIP'' LIMIT 1; EXCEPTION WHEN OTHER THEN v_owner := NULL; END; v_evidence := ''reads_30d='' || :v_reads || '', downstream='' || :v_downstream || '', signal='' || :v_signal; BEGIN SELECT SNOWFLAKE.CORTEX.AI_COMPLETE(''claude-haiku-4-5'', ''Classify the business impact of this data incident in one sentence. Evidence: '' || :v_evidence) INTO v_summary; EXCEPTION WHEN OTHER THEN v_summary := ''AI unavailable. severity='' || :v_severity || '' based on '' || :v_evidence; END; UPDATE ' || :tgt || '.INCIDENTS SET SEVERITY = :v_severity, OWNER = COALESCE(:v_owner, OWNER), AI_SUMMARY = :v_summary WHERE INCIDENT_ID = :P_INCIDENT_ID; INSERT INTO ' || :tgt || '.INCIDENT_EVENTS (INCIDENT_ID, EVENT_TYPE, DETAIL) VALUES (:P_INCIDENT_ID, ''TRIAGE'', :v_evidence); RETURN ''triaged: '' || :v_severity; END');

    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.EXPLAIN_INCIDENT(P_INCIDENT_ID NUMBER) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_fqn VARCHAR; v_signal VARCHAR; v_metric VARCHAR; v_group_id NUMBER; v_failures VARCHAR DEFAULT ''''; v_dml VARCHAR DEFAULT ''''; v_group_ctx VARCHAR DEFAULT ''''; v_hypothesis VARCHAR; BEGIN SELECT OBJECT_FQN, SIGNAL_TYPE, METRIC_NAME, GROUP_ID INTO v_fqn, v_signal, v_metric, v_group_id FROM ' || :tgt || '.INCIDENTS WHERE INCIDENT_ID = :P_INCIDENT_ID; IF (:v_fqn IS NULL) THEN RETURN ''error: not found''; END IF; BEGIN SELECT LISTAGG(NAME || '' failed: '' || COALESCE(ERROR_MESSAGE, ''unknown''), ''; '') WITHIN GROUP (ORDER BY COMPLETED_TIME DESC) INTO v_failures FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE STATE = ''FAILED'' AND COMPLETED_TIME >= DATEADD(HOUR, -24, CURRENT_TIMESTAMP()) AND DATABASE_NAME = SPLIT_PART(:v_fqn, ''.'', 1) LIMIT 5; EXCEPTION WHEN OTHER THEN v_failures := ''unavailable''; END; BEGIN SELECT ''adds='' || SUM(ROWS_ADDED) || '',removes='' || SUM(ROWS_REMOVED) INTO v_dml FROM SNOWFLAKE.ACCOUNT_USAGE.TABLE_DML_HISTORY WHERE TABLE_NAME = SPLIT_PART(:v_fqn, ''.'', 3) AND TABLE_SCHEMA = SPLIT_PART(:v_fqn, ''.'', 2) AND TABLE_CATALOG = SPLIT_PART(:v_fqn, ''.'', 1) AND START_TIME >= DATEADD(HOUR, -24, CURRENT_TIMESTAMP()); EXCEPTION WHEN OTHER THEN v_dml := ''unavailable''; END; IF (:v_group_id IS NOT NULL) THEN BEGIN SELECT LISTAGG(OBJECT_FQN || '' ('' || SIGNAL_TYPE || '')'', '', '') INTO v_group_ctx FROM ' || :tgt || '.INCIDENTS WHERE GROUP_ID = :v_group_id AND INCIDENT_ID != :P_INCIDENT_ID; EXCEPTION WHEN OTHER THEN v_group_ctx := ''''; END; END IF; LET v_ctx VARCHAR := ''Object: '' || :v_fqn || '' Signal: '' || :v_signal || '' Failures: '' || COALESCE(:v_failures, ''none'') || '' DML: '' || COALESCE(:v_dml, ''none'') || '' Group: '' || COALESCE(:v_group_ctx, ''none''); BEGIN SELECT SNOWFLAKE.CORTEX.AI_COMPLETE(''claude-haiku-4-5'', ''Based ONLY on this evidence, provide a root-cause hypothesis in 2-3 sentences: '' || :v_ctx) INTO v_hypothesis; EXCEPTION WHEN OTHER THEN v_hypothesis := ''AI unavailable. Context: '' || :v_ctx; END; UPDATE ' || :tgt || '.INCIDENTS SET ROOT_CAUSE_NOTE = :v_hypothesis WHERE INCIDENT_ID = :P_INCIDENT_ID; RETURN :v_hypothesis; END');

    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.RECOMMEND_MONITORS(P_TOP_N NUMBER DEFAULT 10) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_result VARCHAR DEFAULT ''''; BEGIN SELECT LISTAGG(imp.OBJECT_FQN || '' (reads='' || imp.READ_COUNT_90D || '', consumers='' || imp.DISTINCT_CONSUMERS_90D || '')'', CHR(10)) WITHIN GROUP (ORDER BY imp.READ_COUNT_90D DESC) INTO v_result FROM ' || :tgt || '.V_MONITOR_GAPS imp LIMIT :P_TOP_N; IF (:v_result IS NULL OR :v_result = '''') THEN RETURN ''All important tables already have DMF coverage.''; END IF; LET v_advice VARCHAR := ''''; BEGIN SELECT SNOWFLAKE.CORTEX.AI_COMPLETE(''claude-haiku-4-5'', ''Given these unmonitored high-importance tables, recommend which metrics (freshness, row_count, null_count, etc) to attach and why, in 3-5 bullet points: '' || :v_result) INTO v_advice; EXCEPTION WHEN OTHER THEN v_advice := ''AI unavailable. Top candidates: '' || :v_result; END; RETURN :v_advice; END');

    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.TUNE_THRESHOLD(P_TABLE_FQN VARCHAR, P_METRIC_NAME VARCHAR, P_LOOKBACK_DAYS NUMBER DEFAULT 14) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_stats VARCHAR DEFAULT ''''; v_advice VARCHAR DEFAULT ''''; BEGIN SELECT ''mean='' || ROUND(AVG(VALUE), 4) || '', stddev='' || ROUND(STDDEV(VALUE), 4) || '', min='' || ROUND(MIN(VALUE), 4) || '', max='' || ROUND(MAX(VALUE), 4) || '', anomaly_rate='' || ROUND(DIV0(COUNT_IF(IS_ANOMALY = TRUE), COUNT(*)) * 100, 2) || ''%'' INTO v_stats FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS WHERE TABLE_NAME = SPLIT_PART(:P_TABLE_FQN, ''.'', 3) AND TABLE_SCHEMA = SPLIT_PART(:P_TABLE_FQN, ''.'', 2) AND TABLE_DATABASE = SPLIT_PART(:P_TABLE_FQN, ''.'', 1) AND METRIC_NAME = :P_METRIC_NAME AND MEASUREMENT_TIME >= DATEADD(day, -1 * :P_LOOKBACK_DAYS, CURRENT_TIMESTAMP()); IF (:v_stats IS NULL) THEN RETURN ''No DMF data found for '' || :P_TABLE_FQN || ''.'' || :P_METRIC_NAME; END IF; BEGIN SELECT SNOWFLAKE.CORTEX.AI_COMPLETE(''claude-haiku-4-5'', ''Given these DMF metric statistics for '' || :P_TABLE_FQN || ''.'' || :P_METRIC_NAME || '', recommend if the current anomaly detection sensitivity should be adjusted: '' || :v_stats) INTO v_advice; EXCEPTION WHEN OTHER THEN v_advice := ''AI unavailable. Stats: '' || :v_stats; END; RETURN :v_advice; END');

    stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE PROCEDURE ' || :tgt || '.COST_ADVISOR(P_LOOKBACK_DAYS NUMBER DEFAULT 7) RETURNS VARCHAR LANGUAGE SQL AS DECLARE v_total_credits NUMBER; v_top_wh VARCHAR DEFAULT ''''; v_spill VARCHAR DEFAULT ''''; v_idle VARCHAR DEFAULT ''''; v_advice VARCHAR DEFAULT ''''; BEGIN SELECT SUM(CREDITS_USED) INTO v_total_credits FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE START_TIME >= DATEADD(day, -1 * :P_LOOKBACK_DAYS, CURRENT_TIMESTAMP()); SELECT LISTAGG(WAREHOUSE_NAME || ''='' || ROUND(SUM(CREDITS_USED), 2), '', '') WITHIN GROUP (ORDER BY SUM(CREDITS_USED) DESC) INTO v_top_wh FROM SNOWFLAKE.ACCOUNT_USAGE.WAREHOUSE_METERING_HISTORY WHERE START_TIME >= DATEADD(day, -1 * :P_LOOKBACK_DAYS, CURRENT_TIMESTAMP()) GROUP BY WAREHOUSE_NAME LIMIT 5; SELECT COUNT(*) INTO v_spill FROM SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY WHERE BYTES_SPILLED_TO_REMOTE_STORAGE > 0 AND START_TIME >= DATEADD(day, -1 * :P_LOOKBACK_DAYS, CURRENT_TIMESTAMP()); LET v_evidence VARCHAR := ''credits='' || COALESCE(:v_total_credits::VARCHAR, ''?'') || '', top_wh=['' || COALESCE(:v_top_wh, ''?'') || ''], spill_queries='' || COALESCE(:v_spill, ''?''); BEGIN SELECT SNOWFLAKE.CORTEX.AI_COMPLETE(''claude-haiku-4-5'', ''Provide 2-3 actionable Snowflake cost recommendations based on: '' || :v_evidence) INTO v_advice; EXCEPTION WHEN OTHER THEN v_advice := ''AI unavailable. '' || :v_evidence; END; RETURN :v_advice; END');
  END IF;

  -- ── Alerts (calling RECORD_INCIDENT which auto-triages and auto-notifies) ──
  IF (COALESCE(:do_alerts, FALSE)) THEN
    IF (:sig:task_runs::STRING = 'AVAILABLE') THEN
      stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE ALERT ' || :tgt || '.ALERT_TASK_FAILURES WAREHOUSE = ' || :wh || ' SCHEDULE = ''USING CRON 0 * * * * UTC'' IF (EXISTS (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.TASK_HISTORY WHERE STATE = ''FAILED'' AND COMPLETED_TIME >= DATEADD(hour, -1, CURRENT_TIMESTAMP()))) THEN CALL ' || :tgt || '.RECORD_INCIDENT(''task_failure'', ''TASK_HISTORY'', NULL, ''HIGH'')');
      stmts := ARRAY_APPEND(:stmts, 'ALTER ALERT ' || :tgt || '.ALERT_TASK_FAILURES SUSPEND');
    END IF;

    IF (:sig:dmf_anomalies::STRING = 'AVAILABLE') THEN
      stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE ALERT ' || :tgt || '.ALERT_DMF_ANOMALY WAREHOUSE = ' || :wh || ' SCHEDULE = ''USING CRON 0 * * * * UTC'' IF (EXISTS (SELECT 1 FROM SNOWFLAKE.ACCOUNT_USAGE.AUTOMATIC_DATA_QUALITY_MONITORING_RESULTS WHERE IS_ANOMALY = TRUE AND MEASUREMENT_TIME >= DATEADD(hour, -1, CURRENT_TIMESTAMP()))) THEN CALL ' || :tgt || '.RECORD_INCIDENT(''dmf_anomaly'', ''DMF'', NULL, ''MEDIUM'')');
      stmts := ARRAY_APPEND(:stmts, 'ALTER ALERT ' || :tgt || '.ALERT_DMF_ANOMALY SUSPEND');
    END IF;
  END IF;

  -- ── DMF Attachment (safety reqs 1, 3, 4) ───────────────────────────────────
  LET dmf_targets ARRAY := ARRAY_CONSTRUCT();
  LET dmf_detail  ARRAY := ARRAY_CONSTRUCT();
  IF (:mon_tables IS NULL OR :mon_tables = '*') THEN
    dmf_targets := :importance;
  ELSEIF (:mon_tables IS NOT NULL) THEN
    LET tbl_arr ARRAY := SPLIT(:mon_tables, ',');
    LET ti INT := 0;
    WHILE (:ti < ARRAY_SIZE(:tbl_arr)) DO
      dmf_targets := ARRAY_APPEND(:dmf_targets, OBJECT_CONSTRUCT('table_fqn', TRIM(GET(:tbl_arr, :ti)::STRING), 'dml_ops_per_hour', 0, 'importance_score', 0));
      ti := :ti + 1;
    END WHILE;
  END IF;

  IF (ARRAY_SIZE(:dmf_targets) > 0) THEN
    LET di INT := 0;
    WHILE (:di < ARRAY_SIZE(:dmf_targets)) DO
      LET tbl STRING := GET(:dmf_targets, :di):table_fqn::STRING;
      LET dml_rate NUMBER := COALESCE(GET(:dmf_targets, :di):dml_ops_per_hour::NUMBER, 0);
      LET imp_score NUMBER := COALESCE(GET(:dmf_targets, :di):importance_score::NUMBER, 0);
      -- Every table gets the same interval, from the setting. It used to be
      -- TRIGGER_ON_CHANGES for quiet tables and an hourly cron for busy ones,
      -- which was defensible on cost and impossible to price: TRIGGER_ON_CHANGES
      -- has no cadence, so runs-per-month is a guess about the client's DML rather
      -- than a property of anything this build set, and the monthly figure would
      -- have been a fiction dressed as arithmetic. A fixed interval costs the same
      -- on a quiet table as on a busy one, which is the trade taken here, and it
      -- makes the number on the screen the number Snowflake will bill.
      LET schedule STRING := :dmf_sched;
      -- Per-metric evaluation cost, used only where this account has no serverless
      -- DMF history to measure from. Deliberately the high end: on this account the
      -- measured mean was well under it, so a build with no history quotes a ceiling.
      LET evals_per_month NUMBER := ROUND(43200.0 / :dmf_min, 4);
      LET est_cost NUMBER := ROUND(:evals_per_month * 2 * 0.003, 3);
      LET detail_msg STRING := :tbl || ' | importance=' || :imp_score || ' | schedule=' || :schedule || ' | FRESHNESS + ROW_COUNT | up to ' || :est_cost || ' credits/month before measurement';
      IF (:dml_rate > 50) THEN
        detail_msg := :detail_msg || ' (' || :dml_rate || ' DML ops/hr: a shorter interval would catch staleness sooner and cost proportionally more)';
      END IF;
      IF (:tier <> 'PRODUCTION') THEN
        detail_msg := :detail_msg || ' [' || :tier || ': attached, scheduled, then suspended before this block ends]';
      END IF;
      dmf_detail := ARRAY_APPEND(:dmf_detail, :detail_msg);
      -- Safety req 1: check before ADD + wrap in exception; record into registry on success
      stmts := ARRAY_APPEND(:stmts, 'BEGIN LET existing INT := (SELECT COUNT(*) FROM TABLE(INFORMATION_SCHEMA.DATA_METRIC_FUNCTION_REFERENCES(REF_ENTITY_NAME => ''' || :tbl || ''', REF_ENTITY_DOMAIN => ''TABLE'')) WHERE METRIC_NAME = ''FRESHNESS''); IF (:existing = 0) THEN ALTER TABLE ' || :tbl || ' ADD DATA METRIC FUNCTION SNOWFLAKE.CORE.FRESHNESS ON (); INSERT INTO ' || :tgt || '.ATTACHED_DMF_REGISTRY (TABLE_FQN, DMF_NAME, ARGUMENTS) VALUES (''' || :tbl || ''', ''SNOWFLAKE.CORE.FRESHNESS'', ''''); END IF; EXCEPTION WHEN OTHER THEN NULL; END');
      stmts := ARRAY_APPEND(:stmts, 'BEGIN LET existing INT := (SELECT COUNT(*) FROM TABLE(INFORMATION_SCHEMA.DATA_METRIC_FUNCTION_REFERENCES(REF_ENTITY_NAME => ''' || :tbl || ''', REF_ENTITY_DOMAIN => ''TABLE'')) WHERE METRIC_NAME = ''ROW_COUNT''); IF (:existing = 0) THEN ALTER TABLE ' || :tbl || ' ADD DATA METRIC FUNCTION SNOWFLAKE.CORE.ROW_COUNT ON (); INSERT INTO ' || :tgt || '.ATTACHED_DMF_REGISTRY (TABLE_FQN, DMF_NAME, ARGUMENTS) VALUES (''' || :tbl || ''', ''SNOWFLAKE.CORE.ROW_COUNT'', ''''); END IF; EXCEPTION WHEN OTHER THEN NULL; END');
      stmts := ARRAY_APPEND(:stmts, 'ALTER TABLE ' || :tbl || ' SET DATA_METRIC_SCHEDULE = ''' || :schedule || '''');
      -- Read back what Snowflake thinks it is now, before anything below suspends
      -- it. SCHEDULE arrives normalised to a cron string and SCHEDULE_STATUS says
      -- STARTED, so this row is the account's own confirmation that the monitoring
      -- went live rather than the script's claim that it did. Qualified to the
      -- monitored table's OWN database: the target schema is frequently somewhere
      -- else, and DATA_METRIC_FUNCTION_REFERENCES answers per database.
      stmts := ARRAY_APPEND(:stmts, 'BEGIN INSERT INTO ' || :tgt || '.DMF_SCHEDULE_PROOF (TABLE_FQN, METRIC_NAME, SCHEDULE, SCHEDULE_STATUS, OBSERVED_AT) SELECT ''' || :tbl || ''', METRIC_NAME, SCHEDULE, SCHEDULE_STATUS, CURRENT_TIMESTAMP() FROM TABLE(' || SPLIT_PART(:tbl, '.', 1) || '.INFORMATION_SCHEMA.DATA_METRIC_FUNCTION_REFERENCES(REF_ENTITY_NAME => ''' || :tbl || ''', REF_ENTITY_DOMAIN => ''TABLE'')); EXCEPTION WHEN OTHER THEN NULL; END');
      -- The tier gate. Only PRODUCTION walks away with the schedule still set.
      -- An empty string is how Snowflake suspends every DMF on an object; UNSET
      -- looks like the right verb and is not -- since the 2025_07 bundle it resets
      -- the schedule to the one-hour DEFAULT, which would leave a look-around
      -- build billing serverless credits on tables it does not own.
      IF (:tier <> 'PRODUCTION') THEN
        stmts := ARRAY_APPEND(:stmts, 'ALTER TABLE ' || :tbl || ' SET DATA_METRIC_SCHEDULE = '''''); 
      END IF;
      di := :di + 1;
    END WHILE;

    -- ── What one evaluation actually costs ───────────────────────────────────
    -- DMFs are serverless, so there is no warehouse to read a rate off and no
    -- refresh history to time. What Snowflake does publish is credits per
    -- monitored table per hour, which is the only measured figure available here.
    -- Joined back to the registry so a table this build did not touch cannot
    -- contribute to this build's number.
    stmts := ARRAY_APPEND(:stmts,
      'CREATE OR REPLACE VIEW ' || :tgt || '.V_DMF_EVALUATION_COST AS '
   || 'WITH att AS (SELECT UPPER(TABLE_FQN) AS TABLE_FQN, COUNT(*) AS METRIC_COUNT '
   || '  FROM ' || :tgt || '.ATTACHED_DMF_REGISTRY GROUP BY 1), '
   || 'obs AS (SELECT UPPER(DATABASE_NAME || ''.'' || SCHEMA_NAME || ''.'' || TABLE_NAME) '
   || '    AS TABLE_FQN, COUNT(*) AS OBSERVED_HOURS, '
   || '    ROUND(AVG(CREDITS_USED), 8) AS AVG_CREDITS_PER_HOUR '
   || '  FROM SNOWFLAKE.ACCOUNT_USAGE.DATA_QUALITY_MONITORING_USAGE_HISTORY '
   || '  WHERE START_TIME >= DATEADD(day, -30, CURRENT_TIMESTAMP()) AND CREDITS_USED > 0 '
   || '  GROUP BY 1) '
   || 'SELECT a.TABLE_FQN, a.METRIC_COUNT, o.OBSERVED_HOURS, o.AVG_CREDITS_PER_HOUR, '
      -- An hour of monitoring divided across the evaluations an hour contains.
      -- Exact once the history was produced under the interval this build set,
      -- which is the case on every re-run; on a first build there is no history
      -- at all and the assumed per-metric figure is used instead.
   || '  ROUND(COALESCE(o.AVG_CREDITS_PER_HOUR * ' || :dmf_min || ' / 60.0, '
   || '    a.METRIC_COUNT * 0.003), 8) AS CREDITS_PER_RUN '
   || 'FROM att a LEFT JOIN obs o ON a.TABLE_FQN = o.TABLE_FQN');

    -- ── Register what this leaves RUNNING ────────────────────────────────────
    -- One row per monitored table, because the measurement source is per table
    -- and because the client needs to see which table is carrying the cost, not
    -- a single total that hides a wide table next to a narrow one.
    --
    --   RUNS_PER_MONTH   43,200 minutes / the interval this build SET. A fact
    --                    about the object: the same :dmf_min built the schedule
    --                    string a few statements up.
    --   SECONDS_PER_RUN  NOT warehouse seconds -- there is no warehouse. It is
    --                    credits per evaluation expressed as seconds at 1
    --                    credit/hour, so the shared view's runs x seconds x rate
    --                    / 3600 reproduces the measured credits exactly.
    --   WAREHOUSE_CREDITS_PER_HOUR  1.0, a unit denominator, not a warehouse
    --                    size. Reading SHOW WAREHOUSES here would be the same
    --                    class of error as assuming XS: the wrong instrument.
    stmts := ARRAY_APPEND(:stmts,
      'INSERT INTO ' || :tgt || '.STANDING_WORKLOAD '
   || '(KIND, OBJECT_NAME, CADENCE, RUNS_PER_MONTH, SECONDS_PER_RUN, '
   || ' WAREHOUSE_CREDITS_PER_HOUR, MEASURED_INPUT, BASIS, INSTALLED_AT) '
   || 'SELECT ''DMF'', c.TABLE_FQN, ''' || :dmf_sched || ''', '
   || '  ROUND(43200.0 / ' || :dmf_min || ', 4), '
   || '  ROUND(c.CREDITS_PER_RUN * 3600.0, 4), 1.0, '
   || '  CASE WHEN c.OBSERVED_HOURS IS NOT NULL '
   || '    THEN ''measured: '' || c.AVG_CREDITS_PER_HOUR || '' credits/hour over '' '
   || '      || c.OBSERVED_HOURS || '' monitored hour(s) of this table in '
   || 'ACCOUNT_USAGE.DATA_QUALITY_MONITORING_USAGE_HISTORY'' '
   || '    ELSE ''no serverless DMF history for this table yet; assuming 0.003 '
   || 'credits per metric per evaluation across '' || c.METRIC_COUNT || '' metric(s)'' '
   || '    END, '
   || '  ''' || :dmf_min || '-minute schedule set by this build, so 43200/' || :dmf_min
   || ' = '' || ROUND(43200.0 / ' || :dmf_min || ', 0) || '' evaluations/month. '
   || 'Data quality monitoring is SERVERLESS: the credits are measured directly and '
   || 'SECONDS_PER_RUN carries them at 1 credit/hour rather than describing a '
   || 'warehouse. PROJECTED: the interval is a fact, the per-evaluation cost moves '
   || 'with how much data the table holds next month.'
   || IFF(:tier <> 'PRODUCTION',
          ' NOT CURRENTLY BILLING: this was a ' || :tier || ' build, so the schedule '
       || 'was suspended again before the block ended. The figure is what PRODUCTION '
       || 'would cost.', '') || ''', '
   || '  CURRENT_TIMESTAMP() '
   || 'FROM ' || :tgt || '.V_DMF_EVALUATION_COST c');

    -- The two views the app and the packet read. After the INSERT, so they are
    -- worth querying the moment the build finishes.
    stmts := ARRAY_APPEND(:stmts,
      'CREATE OR REPLACE VIEW ' || :tgt || '.V_MONTHLY_RUN_RATE AS SELECT '
   || 'KIND, OBJECT_NAME, CADENCE, RUNS_PER_MONTH, SECONDS_PER_RUN, '
   || 'WAREHOUSE_CREDITS_PER_HOUR, '
      -- Multiply before dividing: a 1.0/3600.0 constant rounds to scale 6 and
      -- another solution shipped a 4x-low figure that way.
   || 'ROUND(RUNS_PER_MONTH * SECONDS_PER_RUN * WAREHOUSE_CREDITS_PER_HOUR '
   || '  / 3600.0, 4) AS EST_CREDITS_PER_MONTH, '
   || '''PROJECTED'' AS LABEL, MEASURED_INPUT, BASIS, INSTALLED_AT '
   || 'FROM ' || :tgt || '.STANDING_WORKLOAD');
    stmts := ARRAY_APPEND(:stmts,
      'CREATE OR REPLACE VIEW ' || :tgt || '.V_RUN_RATE_HEADLINE AS SELECT '
   || 'CASE WHEN COUNT(*) = 0 THEN '
   || '  ''This build installs nothing that runs on a schedule. It costs storage '
   || 'plus whatever compute the people querying it use.'' '
   || 'ELSE ''About '' || ROUND(SUM(RUNS_PER_MONTH * SECONDS_PER_RUN '
   || '  * WAREHOUSE_CREDITS_PER_HOUR / 3600.0), 2) '
   || '  || '' credits/month across '' || COUNT(*) || '' monitored table(s), '
   || 'PROJECTED from the DMF schedule this build set and serverless credits it '
   || 'measured.'' END AS HEADLINE, COUNT(*) AS COMPONENTS, '
   || 'ROUND(COALESCE(SUM(RUNS_PER_MONTH * SECONDS_PER_RUN '
   || '  * WAREHOUSE_CREDITS_PER_HOUR / 3600.0), 0), 4) AS EST_CREDITS_PER_MONTH '
   || 'FROM ' || :tgt || '.STANDING_WORKLOAD');
  END IF;

  -- ── Streamlit Python + React bundle + CREATE STREAMLIT ─────────────────────
  LET py STRING := 'import streamlit as st' || CHR(10) || 'import streamlit.components.v1 as components' || CHR(10) || 'import json, base64' || CHR(10) || 'from decimal import Decimal' || CHR(10) || 'def _enc(o):' || CHR(10) || '    return float(o) if isinstance(o, Decimal) else str(o)' || CHR(10) || 'st.set_page_config(page_title="Observability Monitor", layout="wide")' || CHR(10) || 'from snowflake.snowpark.context import get_active_session' || CHR(10) || '' || CHR(10) || 'session = get_active_session()' || CHR(10) || '' || CHR(10) || '_APP_JS_B64 = ""' || CHR(10) || '_APP_CSS_B64 = ""' || CHR(10) || '' || CHR(10) || '_ROW_CAP = 20000' || CHR(10) || '_BUDGET_BYTES = 22000000' || CHR(10) || '' || CHR(10) || 'def _query(view):' || CHR(10) || '    try:' || CHR(10) || '        return session.sql("SELECT * FROM ' || :tgt || '." + view + " LIMIT " + str(_ROW_CAP)).collect()' || CHR(10) || '    except:' || CHR(10) || '        return []' || CHR(10) || '' || CHR(10) || '@st.cache_data(ttl=300)' || CHR(10) || 'def load_data():' || CHR(10) || '    views = {}' || CHR(10) || '    notes = []' || CHR(10) || '    used = 0' || CHR(10) || '    for v in ["V_TASK_FAILURES","V_TASK_RELIABILITY","V_COPY_LOADS","V_STREAMING_HEALTH","V_QUERY_PRESSURE","V_SPILL_OFFENDERS","V_QUEUE_PRESSURE","V_BI_QUERY_PRESSURE","V_WAREHOUSE_CREDITS","V_CREDIT_TREND","V_WAREHOUSE_CHURN","V_UNUSED_TABLES","V_DMF_RESULTS","V_DMF_ANOMALIES","V_DQ_SCORECARD","V_ASSET_IMPORTANCE","V_TABLE_IMPORTANCE","V_MONITOR_GAPS","V_ALERT_HISTORY","V_ALERT_RELIABILITY","V_MONITOR_COVERAGE","V_AGENT_TRACES","V_AGENT_LATENCY","V_AGENT_ERRORS","V_EXT_MONITOR_QUERY_FOOTPRINT","V_EXT_MONITOR_CREDIT_TREND","V_EXT_MONITOR_BREAKDOWN","V_INCIDENT_GROUPS","V_SLO_COMPLIANCE","V_FRESHNESS_SLA","V_RECOMMENDATIONS","INCIDENTS","INCIDENT_EVENTS","SLO_POLICY","V_DT_REFRESH_HEALTH","V_PIPE_THROUGHPUT","V_TABLE_FRESHNESS","V_TABLE_DML_TREND"]:' || CHR(10) || '        key = v.lower()[2:] if v.lower().startswith("v_") else v.lower()' || CHR(10) || '        recs = []' || CHR(10) || '        over = False' || CHR(10) || '        for row in _query(v):' || CHR(10) || '            d = row.as_dict()' || CHR(10) || '            n = len(json.dumps(d, default=_enc)) + 1' || CHR(10) || '            if used + n > _BUDGET_BYTES:' || CHR(10) || '                over = True' || CHR(10) || '                break' || CHR(10) || '            used += n' || CHR(10) || '            recs.append(d)' || CHR(10) || '        if over or len(recs) >= _ROW_CAP:' || CHR(10) || '            notes.append(key)' || CHR(10) || '        views[key] = recs' || CHR(10) || '    return views, notes' || CHR(10) || '' || CHR(10) || 'data, _capped = load_data()' || CHR(10) || 'if _capped:' || CHR(10) || '    st.caption("Row counts below are limited so the payload stays inside Streamlit\u2019s 32 MB message limit. Truncated: " + ", ".join(sorted(_capped)))' || CHR(10) || 'js = base64.b64decode(_APP_JS_B64).decode("utf-8")' || CHR(10) || 'css = base64.b64decode(_APP_CSS_B64).decode("utf-8")' || CHR(10) || '_SIGNALS = json.loads(r"""' || REPLACE(TO_JSON(:sig), 'NO ACCESS', 'NO_ACCESS') || '""")' || CHR(10) || 'payload = json.dumps({"signals": _SIGNALS, "views": data, "config": {"window_days": ' || :w || ', "schema": "' || :tgt || '"}}, default=_enc)' || CHR(10) || 'doc = "<!DOCTYPE html><html><head><meta charset=''utf-8''><style>" + css + "</style></head><body><div id=''app-root''></div><script>window.__OBSERVABILITY_DATA__ = " + payload + ";" + js + "</script></body></html>"' || CHR(10) || 'components.html(doc, height=960, scrolling=True)' || CHR(10) || '';

  -- BEGIN GENERATED OBSERVABILITY VIEWER
  py := REPLACE(:py, 'session = get_active_session()', 'session = get_active_session()' || CHR(10) || BASE64_DECODE_STRING(''));
  py := REPLACE(:py, 'payload = json.dumps({', 'payload = json.dumps({"navigation": _APP_NAVIGATION, ');
  -- END GENERATED OBSERVABILITY VIEWER

  stmts := ARRAY_APPEND(:stmts, 'COPY INTO @' || :tgt || '.APP_STAGE/streamlit_app.py FROM (SELECT ''' || REPLACE(:py, '''', '''''') || ''') FILE_FORMAT = (TYPE = CSV COMPRESSION = NONE FIELD_DELIMITER = NONE RECORD_DELIMITER = NONE FIELD_OPTIONALLY_ENCLOSED_BY = NONE ESCAPE_UNENCLOSED_FIELD = NONE) OVERWRITE = TRUE SINGLE = TRUE');
  stmts := ARRAY_APPEND(:stmts, 'CREATE OR REPLACE STREAMLIT ' || :tgt || '.OBSERVABILITY_MONITOR ROOT_LOCATION = ''@' || :tgt || '.APP_STAGE'' MAIN_FILE = ''streamlit_app.py'' QUERY_WAREHOUSE = ' || :wh || ' COMMENT = ''Observability Monitor - generated from account discovery''');

  -- ── Gate ───────────────────────────────────────────────────────────────────
  -- The plan lives in the local :stmts array. It is deliberately NOT pushed
  -- through a session variable: session variables are capped at 16,384 bytes and
  -- this plan is far larger, so the inherited two-block handoff could never have
  -- worked here. Generating and executing in one block also removes the chance of
  -- a build running against a plan produced in some earlier session.
  LET approved BOOLEAN := FALSE;
  BEGIN
    approved := (SELECT TRY_CAST($MONITOR_APPROVE::VARCHAR AS BOOLEAN));
  EXCEPTION WHEN OTHER THEN approved := FALSE;
  END;

  IF (NOT COALESCE(:approved, FALSE)) THEN
  res := (
    SELECT 0 AS step, 'TARGET' AS action, :tgt || '  |  ' || :w || ' day window  |  warehouse ' || :wh || '  |  ' || ARRAY_SIZE(:stmts) || ' statements' AS statement
    UNION ALL SELECT 1, 'NOTIFICATION', COALESCE('Delivering via ' || :notif, 'SKIPPED - logging to event table only')
    UNION ALL SELECT 2, 'DMF TARGETS', IFF(ARRAY_SIZE(:dmf_targets) > 0, ARRAY_SIZE(:dmf_targets) || ' tables for FRESHNESS + ROW_COUNT (auto-selected top-' || :top_n || ' by importance)', 'NONE — importance list empty (check ACCESS_HISTORY or lower MONITOR_TOP_N)')
    UNION ALL
    SELECT 3 + ROW_NUMBER() OVER (ORDER BY INDEX) * 0, 'DMF DETAIL', VALUE::STRING
    FROM TABLE(FLATTEN(input => :dmf_detail))
    UNION ALL SELECT 4, 'TEARDOWN', 'After build: CALL ' || :tgt || '.TEARDOWN();'
    UNION ALL SELECT 5, 'READ FIRST', 'SELECT * FROM ' || :tgt || '.V_MONITOR_COVERAGE;'
    UNION ALL
    SELECT 10 + INDEX, 'WILL RUN (only if approved)',
           IFF(LENGTH(VALUE::STRING) > 400, LEFT(VALUE::STRING, 300) || ' ... [' || LENGTH(VALUE::STRING) || ' chars]', VALUE::STRING)
    FROM TABLE(FLATTEN(input => :stmts))
    ORDER BY step
  );
    RETURN TABLE(res);
  END IF;

  -- ── APPROVED: build ────────────────────────────────────────────────────────
  -- Executes the statements printed above, in order, stopping at the first
  -- failure because later statements depend on earlier ones.
  LET log   ARRAY := ARRAY_CONSTRUCT();
  LET i     INT   := 0;

  WHILE (:i < ARRAY_SIZE(:stmts)) DO
    LET s STRING := GET(:stmts, :i)::STRING;
    BEGIN
      EXECUTE IMMEDIATE :s;
      log := ARRAY_APPEND(:log, OBJECT_CONSTRUCT('n', :i + 1, 'status', 'OK',
                                                 'stmt', LEFT(:s, 120), 'error', ''));
    EXCEPTION WHEN OTHER THEN
      log := ARRAY_APPEND(:log, OBJECT_CONSTRUCT('n', :i + 1, 'status', 'FAILED',
                                                 'stmt', LEFT(:s, 120), 'error', SQLERRM));
      i := ARRAY_SIZE(:stmts);   -- stop at first failure
    END;
    i := :i + 1;
  END WHILE;

  -- Create the TEARDOWN procedure (uses ATTACHED_DMF_REGISTRY for cross-schema detach)
  BEGIN
    EXECUTE IMMEDIATE
      'CREATE OR REPLACE PROCEDURE ' || :tgt || '.TEARDOWN() RETURNS VARCHAR LANGUAGE SQL AS '
   || 'DECLARE r RESULTSET; detached INT DEFAULT 0; failed INT DEFAULT 0; failed_items ARRAY DEFAULT ARRAY_CONSTRUCT(); BEGIN '
   || 'r := (SELECT TABLE_FQN, DMF_NAME, ARGUMENTS FROM ' || :tgt || '.ATTACHED_DMF_REGISTRY); '
   || 'FOR rec IN r DO '
   || 'BEGIN EXECUTE IMMEDIATE ''ALTER TABLE '' || rec.TABLE_FQN || '' DROP DATA METRIC FUNCTION '' || rec.DMF_NAME || '' ON ('' || rec.ARGUMENTS || '')''; '
   || 'detached := :detached + 1; '
   || 'EXCEPTION WHEN OTHER THEN failed := :failed + 1; failed_items := ARRAY_APPEND(:failed_items, rec.TABLE_FQN || '': '' || SQLERRM); END; '
      -- The schedule is a table PARAMETER, so dropping the metrics does not remove
      -- it. Nothing bills once no DMF is attached, but leaving DATA_METRIC_SCHEDULE
      -- set on a customer's table means the next DMF anyone attaches inherits a
      -- cadence this script chose. Repeated once per metric row, which is harmless.
   || 'BEGIN EXECUTE IMMEDIATE ''ALTER TABLE '' || rec.TABLE_FQN || '' UNSET DATA_METRIC_SCHEDULE''; EXCEPTION WHEN OTHER THEN NULL; END; '
   || 'END FOR; '
   || 'EXECUTE IMMEDIATE ''DROP ALERT IF EXISTS ' || :tgt || '.ALERT_TASK_FAILURES''; '
   || 'EXECUTE IMMEDIATE ''DROP ALERT IF EXISTS ' || :tgt || '.ALERT_DMF_ANOMALY''; '
   || 'EXECUTE IMMEDIATE ''DROP ALERT IF EXISTS ' || :tgt || '.ALERT_SPILL_SURGE''; '
   || 'EXECUTE IMMEDIATE ''DROP SCHEMA IF EXISTS ' || :tgt || ' CASCADE''; '
   || 'RETURN ''Teardown complete. Detached '' || :detached || '' DMFs ('' || :failed || '' failed to detach).'' '
   || '|| IFF(:failed > 0, CHR(10) || ''Failed: '' || ARRAY_TO_STRING(:failed_items, CHR(10)), ''''); END';
    log := ARRAY_APPEND(:log, OBJECT_CONSTRUCT('n', ARRAY_SIZE(:stmts) + 1, 'status', 'OK',
                                               'stmt', 'CREATE PROCEDURE TEARDOWN()', 'error', ''));
  EXCEPTION WHEN OTHER THEN
    log := ARRAY_APPEND(:log, OBJECT_CONSTRUCT('n', ARRAY_SIZE(:stmts) + 1, 'status', 'FAILED',
                                               'stmt', 'CREATE PROCEDURE TEARDOWN()', 'error', SQLERRM));
  END;

  res := (
    SELECT v.value:n::INT AS n, v.value:status::STRING AS status,
           v.value:stmt::STRING AS statement, v.value:error::STRING AS error
    FROM TABLE(FLATTEN(input => :log)) v
    UNION ALL
    SELECT 96, 'READ FIRST', 'SELECT * FROM ' || :tgt || '.V_MONITOR_COVERAGE;', ''
    UNION ALL
    SELECT 96, 'WHAT THIS COSTS PER MONTH', 'SELECT * FROM ' || :tgt || '.V_RUN_RATE_HEADLINE;', ''
    UNION ALL
    SELECT 97, 'OPEN THE APP', 'Snowsight > Projects > Streamlit > OBSERVABILITY_MONITOR', ''
    UNION ALL
    SELECT 98, 'TO REMOVE EVERYTHING', 'CALL ' || :tgt || '.TEARDOWN();', ''
    ORDER BY n
  );
  RETURN TABLE(res);
END;
$$;


-- ===========================================================================
-- BLOCK 3 · UPSTREAM COLLECTORS  (the pull side)
--
-- Blocks 0-2 report on work that already reached Snowflake. This block
-- reverses the direction: Snowflake polls Airflow, Prometheus and Confluent
-- and turns their answers into ordinary rows.
--
-- It exists because Snowflake's external-lineage API accepts only COMPLETE
-- events and its edges are not returned by GET_LINEAGE, so a FAILED Airflow
-- DAG produces nothing you can query, wrap in a DMF, or alert on. A polled
-- row has none of those limits.
--
-- Gated independently on MONITOR_UPSTREAM. With the gate FALSE it prints a
-- plan and an operator runbook and creates nothing.
-- ===========================================================================
EXECUTE IMMEDIATE $$
DECLARE
  gate            BOOLEAN DEFAULT FALSE;
  tgt             VARCHAR;
  eai             VARCHAR DEFAULT '';
  seed            BOOLEAN DEFAULT TRUE;
  py              VARCHAR;
  stmts           ARRAY   DEFAULT ARRAY_CONSTRUCT();
  runbook         ARRAY   DEFAULT ARRAY_CONSTRUCT();
  notes           ARRAY   DEFAULT ARRAY_CONSTRUCT();
  s               VARCHAR;
  n               INT     DEFAULT 0;
  created         INT     DEFAULT 0;
  failed          INT     DEFAULT 0;
  errs            ARRAY   DEFAULT ARRAY_CONSTRUCT();
  has_incidents   BOOLEAN DEFAULT FALSE;
  can_integrate   BOOLEAN DEFAULT FALSE;
  wh              VARCHAR DEFAULT '';
  q               VARCHAR;
BEGIN
  -- ---------------------------------------------------------------- settings
  BEGIN gate := (SELECT TRY_TO_BOOLEAN(GETVARIABLE('MONITOR_UPSTREAM')::VARCHAR)); EXCEPTION WHEN OTHER THEN gate := FALSE; END;
  gate := COALESCE(:gate, FALSE);
  BEGIN eai  := (SELECT COALESCE(GETVARIABLE('MONITOR_UPSTREAM_EAI')::VARCHAR, '')); EXCEPTION WHEN OTHER THEN eai := ''; END;
  BEGIN seed := (SELECT TRY_TO_BOOLEAN(GETVARIABLE('MONITOR_UPSTREAM_SEED')::VARCHAR)); EXCEPTION WHEN OTHER THEN seed := TRUE; END;
  seed := COALESCE(:seed, TRUE);
  -- Reuse the script's warehouse if one was named. Without it the task is
  -- serverless, which needs EXECUTE MANAGED TASK and is not permitted on every
  -- account.
  BEGIN wh := (SELECT COALESCE(GETVARIABLE('MONITOR_APP_WAREHOUSE')::VARCHAR, '')); EXCEPTION WHEN OTHER THEN wh := ''; END;
  wh := COALESCE(:wh, '');

  -- Target schema: reuse whatever Block 2 built.
  BEGIN
    tgt := (SELECT NULLIF(GETVARIABLE('MONITOR_TARGET_DB')::VARCHAR,'') || '.' ||
                   COALESCE(NULLIF(GETVARIABLE('MONITOR_SCHEMA')::VARCHAR,''),'OBSERVABILITY_MONITOR'));
  EXCEPTION WHEN OTHER THEN tgt := NULL; END;
  IF (:tgt IS NULL OR :tgt LIKE '.%') THEN
    tgt := CURRENT_DATABASE() || '.' || COALESCE(NULLIF(GETVARIABLE('MONITOR_SCHEMA')::VARCHAR,''),'OBSERVABILITY_MONITOR');
  END IF;

  -- Does the incident lifecycle from Block 2 exist? If so we bridge into it
  -- instead of inventing a second alerting path.
  BEGIN
    q := 'SELECT COUNT(*) FROM ' || SPLIT_PART(:tgt,'.',1) ||
         '.INFORMATION_SCHEMA.PROCEDURES WHERE PROCEDURE_SCHEMA = ''' ||
         SPLIT_PART(:tgt,'.',2) || ''' AND PROCEDURE_NAME = ''RECORD_INCIDENT''';
    EXECUTE IMMEDIATE :q;
    SELECT "COUNT(*)" > 0 INTO has_incidents FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
  EXCEPTION WHEN OTHER THEN has_incidents := FALSE; END;

  -- Can this role create the account-level objects the pull side needs?
  BEGIN
    EXECUTE IMMEDIATE 'SHOW GRANTS TO ROLE ' || CURRENT_ROLE();
    SELECT COUNT(*) > 0 INTO can_integrate
    FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()))
    WHERE "privilege" IN ('CREATE INTEGRATION','OWNERSHIP') OR CURRENT_ROLE() = 'ACCOUNTADMIN';
  EXCEPTION WHEN OTHER THEN can_integrate := (CURRENT_ROLE() = 'ACCOUNTADMIN'); END;

  -- ------------------------------------------------------------ the runbook
  -- Emitted whether or not the gate is open: this is the part a platform team
  -- has to run, and they need to see it before deciding.
  runbook := ARRAY_APPEND(:runbook,
    'STEP 1 (ACCOUNTADMIN) — allow egress only to the hosts you actually poll:' || CHR(10) ||
    'CREATE OR REPLACE NETWORK RULE ' || :tgt || '.UPSTREAM_EGRESS_RULE' || CHR(10) ||
    '  MODE = EGRESS TYPE = HOST_PORT' || CHR(10) ||
    '  VALUE_LIST = (''airflow.internal.example.com:443'', ''prometheus.internal.example.com:9090'', ''api.telemetry.confluent.cloud:443'');');
  runbook := ARRAY_APPEND(:runbook,
    'STEP 2 (ACCOUNTADMIN) — one secret per upstream system. Never put these in SET:' || CHR(10) ||
    'CREATE OR REPLACE SECRET ' || :tgt || '.SEC_AIRFLOW' || CHR(10) ||
    '  TYPE = PASSWORD USERNAME = ''svc_snowflake_observability'' PASSWORD = ''<rotate-me>'';' || CHR(10) ||
    'CREATE OR REPLACE SECRET ' || :tgt || '.SEC_CONFLUENT' || CHR(10) ||
    '  TYPE = PASSWORD USERNAME = ''<cloud-api-key>'' PASSWORD = ''<cloud-api-secret>'';');
  runbook := ARRAY_APPEND(:runbook,
    'STEP 3 (ACCOUNTADMIN) — the integration, then hand it back:' || CHR(10) ||
    'CREATE OR REPLACE EXTERNAL ACCESS INTEGRATION OBSERVABILITY_UPSTREAM_EAI' || CHR(10) ||
    '  ALLOWED_NETWORK_RULES = (' || :tgt || '.UPSTREAM_EGRESS_RULE)' || CHR(10) ||
    '  ALLOWED_AUTHENTICATION_SECRETS = (' || :tgt || '.SEC_AIRFLOW, ' || :tgt || '.SEC_CONFLUENT)' || CHR(10) ||
    '  ENABLED = TRUE;' || CHR(10) ||
    'GRANT USAGE ON INTEGRATION OBSERVABILITY_UPSTREAM_EAI TO ROLE ' || CURRENT_ROLE() || ';' || CHR(10) ||
    'GRANT READ ON SECRET ' || :tgt || '.SEC_AIRFLOW TO ROLE ' || CURRENT_ROLE() || ';');
  runbook := ARRAY_APPEND(:runbook,
    'STEP 4 — re-run this script with:' || CHR(10) ||
    '  SET MONITOR_UPSTREAM = TRUE;' || CHR(10) ||
    '  SET MONITOR_UPSTREAM_EAI = ''OBSERVABILITY_UPSTREAM_EAI'';');
  runbook := ARRAY_APPEND(:runbook,
    'STEP 5 — register real sources, point them at the secrets, then rebind:' || CHR(10) ||
    '  UPDATE ' || :tgt || '.UPSTREAM_SOURCE SET BASE_URL=''https://airflow.internal.example.com'',' || CHR(10) ||
    '     SECRET_NAME=''' || :tgt || '.SEC_AIRFLOW'', ENABLED=TRUE WHERE SOURCE_KEY=''airflow_prod'';' || CHR(10) ||
    '  CALL ' || :tgt || '.REBIND_UPSTREAM_COLLECTOR();   -- required after ANY secret change' || CHR(10) ||
    '  CALL ' || :tgt || '.COLLECT_ALL_UPSTREAM();');

  -- A constraint worth stating plainly rather than discovering in production.
  notes := ARRAY_APPEND(:notes,
    'SECRETS and EXTERNAL_ACCESS_INTEGRATIONS are bound at CREATE time and cannot be ' ||
    'chosen at runtime. A collector therefore cannot read a secret that was added to the ' ||
    'registry after it was built. REBIND_UPSTREAM_COLLECTOR() regenerates the procedure ' ||
    'from the registry and must be called after adding or repointing any credential.');
  notes := ARRAY_APPEND(:notes,
    'Postgres replication lag, WAL growth and bloat have no HTTP surface. This block ' ||
    'reaches them through postgres_exporter over the PROMETHEUS collector. A direct ' ||
    'connection needs a driver, which means SPCS, not a Python UDF.');

  -- ------------------------------------------------------------- gate closed
  IF (NOT :gate) THEN
    RETURN OBJECT_CONSTRUCT(
      'block', 'BLOCK 3 · UPSTREAM COLLECTORS',
      'status', 'PLANNED — nothing created',
      'gate', 'SET MONITOR_UPSTREAM = TRUE to build',
      'target_schema', :tgt,
      'role', CURRENT_ROLE(),
      'can_create_integration', :can_integrate,
      'incident_lifecycle_present', :has_incidents,
      'would_create', ARRAY_CONSTRUCT(
        :tgt || '.UPSTREAM_SOURCE            (registry: one row per upstream system)',
        :tgt || '.UPSTREAM_PROBE             (one row per HTTP call, success or not)',
        :tgt || '.UPSTREAM_SIGNAL            (normalised: entity, state, staleness, value)',
        :tgt || '.COLLECT_UPSTREAM           (Python, egress, per-source dispatch)',
        :tgt || '.REBIND_UPSTREAM_COLLECTOR  (regenerates the above from the registry)',
        :tgt || '.COLLECT_ALL_UPSTREAM       (loops enabled sources)',
        :tgt || '.RAISE_UPSTREAM_INCIDENTS   (bridges failing signals into INCIDENTS)',
        :tgt || '.V_UPSTREAM_HEALTH          (latest state per entity)',
        :tgt || '.V_UPSTREAM_STALE           (entities past their staleness budget)',
        :tgt || '.TASK_COLLECT_UPSTREAM      (created SUSPENDED)'),
      'supported_kinds', ARRAY_CONSTRUCT(
        'AIRFLOW_DAG_RUNS   GET /api/v1/dags/~/dagRuns — run state, duration, last success',
        'AIRFLOW_DAGS       GET /api/v1/dags          — paused/active, schedule',
        'PROMETHEUS         GET /api/v1/query         — postgres_exporter, Kafka JMX, anything',
        'CONFLUENT_METRICS  POST /v2/metrics/cloud/query — consumer_lag_offsets',
        'HTTP_JSON          any JSON endpoint, extraction described in config'),
      'operator_runbook', :runbook,
      'constraints', :notes);
  END IF;

  -- --------------------------------------------------------------- the build
  IF (:eai = '') THEN
    RETURN OBJECT_CONSTRUCT(
      'block', 'BLOCK 3 · UPSTREAM COLLECTORS',
      'status', 'BLOCKED — no external access integration supplied',
      'reason', 'Egress from Snowflake requires an EXTERNAL ACCESS INTEGRATION. ' ||
                'Set MONITOR_UPSTREAM_EAI to one this role can USAGE.',
      'role', CURRENT_ROLE(),
      'can_create_integration', :can_integrate,
      'operator_runbook', :runbook,
      'constraints', :notes);
  END IF;

  -- Block 3 is gated independently of Block 2, so it cannot assume Block 2 ran.
  -- Create the schema if it is missing rather than failing sixteen times over.
  stmts := ARRAY_APPEND(:stmts, 'CREATE SCHEMA IF NOT EXISTS ' || :tgt);

  -- Registry. One row per upstream system.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE TABLE IF NOT EXISTS ' || :tgt || '.UPSTREAM_SOURCE (' ||
    'SOURCE_KEY VARCHAR NOT NULL PRIMARY KEY, ' ||
    'KIND VARCHAR NOT NULL, ' ||
    'BASE_URL VARCHAR NOT NULL, ' ||
    'SECRET_NAME VARCHAR, ' ||
    'AUTH_KIND VARCHAR DEFAULT ''BASIC'', ' ||
    'ENABLED BOOLEAN DEFAULT FALSE, ' ||
    'POLL_MINUTES NUMBER DEFAULT 10, ' ||
    'STALENESS_WARN_SEC NUMBER DEFAULT 3600, ' ||
    'STALENESS_CRIT_SEC NUMBER DEFAULT 10800, ' ||
    'CONFIG VARIANT, ' ||
    'DESCRIPTION VARCHAR, ' ||
    'CREATED_AT TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(), ' ||
    'UPDATED_AT TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP())');

  -- Every HTTP call lands here, including the ones that fail. A collector that
  -- silently stops polling is the failure mode this table exists to catch.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE TABLE IF NOT EXISTS ' || :tgt || '.UPSTREAM_PROBE (' ||
    'PROBE_ID NUMBER AUTOINCREMENT PRIMARY KEY, ' ||
    'PROBE_KEY VARCHAR, ' ||
    'PROBE_AT TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(), ' ||
    'SOURCE_KEY VARCHAR, ' ||
    'KIND VARCHAR, ' ||
    'REQUEST_URL VARCHAR, ' ||
    'HTTP_STATUS NUMBER, ' ||
    'OK BOOLEAN, ' ||
    'LATENCY_MS NUMBER, ' ||
    'SIGNAL_COUNT NUMBER DEFAULT 0, ' ||
    'ERROR_MESSAGE VARCHAR, ' ||
    'PAYLOAD_BYTES NUMBER, ' ||
    'PAYLOAD_SAMPLE VARCHAR)');

  -- Normalised signals. Deliberately source-agnostic so that alerts, DMFs and
  -- the incident model never learn what Airflow is.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE TABLE IF NOT EXISTS ' || :tgt || '.UPSTREAM_SIGNAL (' ||
    'SIGNAL_ID NUMBER AUTOINCREMENT PRIMARY KEY, ' ||
    'PROBE_ID NUMBER, ' ||
    'SIGNAL_AT TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(), ' ||
    'SOURCE_KEY VARCHAR, ' ||
    'KIND VARCHAR, ' ||
    'ENTITY VARCHAR, ' ||
    'ENTITY_KIND VARCHAR, ' ||
    'SIGNAL_NAME VARCHAR, ' ||
    'STATE VARCHAR, ' ||
    'IS_FAILING BOOLEAN DEFAULT FALSE, ' ||
    'OBSERVED_AT TIMESTAMP_LTZ, ' ||
    'LAST_SUCCESS_AT TIMESTAMP_LTZ, ' ||
    'STALENESS_SEC NUMBER, ' ||
    'VALUE_NUM FLOAT, ' ||
    'DETAIL VARIANT)');

  -- CREATE TABLE IF NOT EXISTS will not reshape a table an earlier version
  -- already created, so top up the newer columns explicitly.
  stmts := ARRAY_APPEND(:stmts,
    'ALTER TABLE ' || :tgt || '.UPSTREAM_SIGNAL ADD COLUMN IF NOT EXISTS SIGNAL_NAME VARCHAR');
  stmts := ARRAY_APPEND(:stmts,
    'ALTER TABLE ' || :tgt || '.UPSTREAM_PROBE ADD COLUMN IF NOT EXISTS PROBE_KEY VARCHAR');

  -- ------------------------------------------------------ the collector body
  -- Written with double quotes only, so it can be embedded as a single-quoted
  -- SQL literal without escaping. CHR(39) supplies the delimiters below.
  py := 'import _snowflake
import requests
import json
import uuid
from datetime import datetime, timezone

SCHEMA_FQN = "__TGT__"
MAX_SAMPLE = 3000


def _utcnow():
    return datetime.now(timezone.utc)


def _ts(v):
    if v is None or v == "":
        return None
    s = str(v)
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    try:
        d = datetime.fromisoformat(s)
    except Exception:
        return None
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return d


def _age(d, ref):
    if d is None:
        return None
    return int((ref - d).total_seconds())


def _iso(d):
    if d is None:
        return None
    return d.isoformat()


def _dig(obj, path):
    cur = obj
    for part in str(path).split("."):
        if part == "":
            continue
        if isinstance(cur, dict):
            cur = cur.get(part)
        elif isinstance(cur, list):
            try:
                cur = cur[int(part)]
            except Exception:
                return None
        else:
            return None
        if cur is None:
            return None
    return cur


def _creds(slot, auth_kind, cfg):
    """Returns (basic_tuple, extra_headers). Slot is the alias bound at CREATE time."""
    if not slot:
        return None, {}
    k = str(auth_kind or "BASIC").upper()
    if k == "BASIC":
        c = _snowflake.get_username_password(slot)
        return (c.username, c.password), {}
    if k == "BEARER":
        return None, {"Authorization": "Bearer " + _snowflake.get_generic_secret_string(slot)}
    if k == "OAUTH":
        return None, {"Authorization": "Bearer " + _snowflake.get_oauth_access_token(slot)}
    if k == "HEADER":
        hn = cfg.get("header_name") or "X-API-Key"
        return None, {hn: _snowflake.get_generic_secret_string(slot)}
    return None, {}


def _parse_airflow_runs(body, ref, cfg):
    runs = body.get("dag_runs") or []

    def sk(r):
        d = _ts(r.get("start_date")) or _ts(r.get("logical_date")) or _ts(r.get("execution_date"))
        return d or datetime(1970, 1, 1, tzinfo=timezone.utc)

    last_success = {}
    for r in runs:
        if str(r.get("state") or "").lower() == "success":
            dag = r.get("dag_id")
            t = _ts(r.get("end_date")) or _ts(r.get("start_date"))
            if dag and t is not None:
                if dag not in last_success or t > last_success[dag]:
                    last_success[dag] = t

    out = []
    seen = {}
    for r in sorted(runs, key=sk, reverse=True):
        dag = r.get("dag_id")
        if not dag or dag in seen:
            continue
        seen[dag] = 1
        state = str(r.get("state") or "unknown").lower()
        sd = _ts(r.get("start_date"))
        ed = _ts(r.get("end_date"))
        dur = None
        if sd is not None and ed is not None:
            dur = int((ed - sd).total_seconds())
        anchor = ed or sd
        out.append({
            "entity": dag,
            "entity_kind": "dag",
            "signal_name": "dag_run_state",
            "state": state,
            "is_failing": state == "failed",
            "observed_at": anchor,
            "last_success_at": last_success.get(dag),
            "staleness_sec": _age(last_success.get(dag) or anchor, ref),
            "value_num": dur,
            "detail": {
                "dag_run_id": r.get("dag_run_id"),
                "run_type": r.get("run_type"),
                "logical_date": r.get("logical_date"),
                "start_date": r.get("start_date"),
                "end_date": r.get("end_date"),
                "duration_sec": dur,
                "external_trigger": r.get("external_trigger"),
                "note": r.get("note"),
                "runs_considered": len(runs),
                "total_entries": body.get("total_entries"),
            },
        })
    return out


def _parse_airflow_dags(body, ref, cfg):
    paused_fails = bool(cfg.get("paused_is_failing"))
    out = []
    for d in (body.get("dags") or []):
        paused = bool(d.get("is_paused"))
        out.append({
            "entity": d.get("dag_id"),
            "entity_kind": "dag_config",
            "signal_name": "dag_paused",
            "state": "paused" if paused else "active",
            "is_failing": paused and paused_fails,
            "observed_at": None,
            "last_success_at": None,
            "staleness_sec": None,
            "value_num": None,
            "detail": {
                "is_active": d.get("is_active"),
                "is_paused": paused,
                "fileloc": d.get("fileloc"),
                "owners": d.get("owners"),
                "tags": d.get("tags"),
                "next_dagrun": d.get("next_dagrun"),
                "schedule_interval": d.get("schedule_interval"),
                "description": d.get("description"),
            },
        })
    return out


def _grade(val, warn, crit, direction="above"):
    """Thresholds are directional. Replication lag is bad when high; a healthy
    replica count or an up probe is bad when low."""
    if val is None:
        return "unknown", False
    if str(direction or "above").lower() == "below":
        if crit is not None and val <= crit:
            return "critical", True
        if warn is not None and val <= warn:
            return "warning", False
        return "ok", False
    if crit is not None and val >= crit:
        return "critical", True
    if warn is not None and val >= warn:
        return "warning", False
    return "ok", False


def _parse_prometheus(body, ref, cfg, qspec):
    res = _dig(body, "data.result") or []
    warn = qspec.get("warn")
    crit = qspec.get("crit")
    lbl = qspec.get("entity_label") or cfg.get("entity_label")
    qname = qspec.get("name") or qspec.get("expr")
    out = []
    for series in res:
        m = series.get("metric") or {}
        raw = series.get("value") or series.get("values")
        val = None
        vts = None
        if isinstance(raw, list) and len(raw) >= 2 and not isinstance(raw[0], list):
            try:
                val = float(raw[1])
            except Exception:
                val = None
            try:
                vts = datetime.fromtimestamp(float(raw[0]), tz=timezone.utc)
            except Exception:
                vts = None
        ent = None
        if lbl:
            ent = m.get(lbl)
        if not ent:
            ent = m.get("instance") or m.get("job") or m.get("__name__") or qname
        state, failing = _grade(val, warn, crit, qspec.get("direction"))
        out.append({
            "entity": str(ent),
            "entity_kind": qspec.get("entity_kind") or cfg.get("entity_kind") or "metric",
            "signal_name": str(qname),
            "state": state,
            "is_failing": failing,
            "observed_at": vts,
            "last_success_at": None,
            "staleness_sec": _age(vts, ref),
            "value_num": val,
            "detail": {"query_name": qname, "expr": qspec.get("expr"), "labels": m,
                       "warn": warn, "crit": crit, "direction": qspec.get("direction") or "above"},
        })
    return out


def _parse_confluent(body, ref, cfg):
    warn = cfg.get("warn")
    crit = cfg.get("crit")
    out = []
    for row in (body.get("data") or []):
        val = None
        try:
            val = float(row.get("value"))
        except Exception:
            val = None
        grp = row.get("metric.consumer_group_id") or row.get("consumer_group_id")
        top = row.get("metric.topic") or row.get("topic")
        if grp and top:
            ent = str(grp) + "/" + str(top)
        elif top:
            ent = str(top)
        else:
            ent = str(grp or "cluster")
        state, failing = _grade(val, warn, crit, cfg.get("direction"))
        vts = _ts(row.get("timestamp"))
        out.append({
            "entity": ent,
            "entity_kind": "consumer_group_topic",
            "signal_name": str(cfg.get("metric") or "consumer_lag_offsets").split("/")[-1],
            "state": state,
            "is_failing": failing,
            "observed_at": vts,
            "last_success_at": None,
            "staleness_sec": _age(vts, ref),
            "value_num": val,
            "detail": {"raw": row, "warn": warn, "crit": crit},
        })
    return out


def _parse_generic(body, ref, cfg):
    recs = _dig(body, cfg.get("records_path")) if cfg.get("records_path") else body
    if isinstance(recs, dict):
        recs = [recs]
    if not isinstance(recs, list):
        return []
    f_ent = cfg.get("entity_field") or "id"
    f_state = cfg.get("state_field") or "state"
    f_time = cfg.get("time_field")
    f_val = cfg.get("value_field")
    bad = [str(x).lower() for x in (cfg.get("failing_states") or ["failed", "fail", "error", "down"])]
    out = []
    for r in recs:
        if not isinstance(r, dict):
            continue
        st = str(_dig(r, f_state) or "unknown").lower()
        t = _ts(_dig(r, f_time)) if f_time else None
        val = None
        if f_val:
            try:
                val = float(_dig(r, f_val))
            except Exception:
                val = None
        out.append({
            "entity": str(_dig(r, f_ent) or "unknown"),
            "entity_kind": cfg.get("entity_kind") or "record",
            "signal_name": cfg.get("signal_name") or "record_state",
            "state": st,
            "is_failing": st in bad,
            "observed_at": t,
            "last_success_at": None,
            "staleness_sec": _age(t, ref),
            "value_num": val,
            "detail": r,
        })
    return out


def _path(cfg, default):
    """Explicit empty string means the base URL is already the whole URL."""
    if "path" in cfg:
        return str(cfg["path"])
    return default


def _overridden(cfg):
    return "path" in cfg


def _fetch(url, method, basic, headers, jbody, timeout):
    if str(method).upper() == "POST":
        return requests.post(url, auth=basic, headers=headers, json=jbody, timeout=timeout)
    return requests.get(url, auth=basic, headers=headers, timeout=timeout)


def _write_probe(session, src_key, kind, url, status, ok, ms, err, nbytes, sample, nsig):
    # Same text-bind-then-cast discipline as the signal writer: an errored probe
    # has a NULL status and latency, and those must not become the string None.
    #
    # AUTOINCREMENT values in Snowflake are unique but NOT monotonic, so
    # MAX(PROBE_ID) can name a different probe than the one just written. The
    # collector therefore generates its own key and looks the id up by it.
    pkey = str(uuid.uuid4())
    session.sql(
        "INSERT INTO " + SCHEMA_FQN + ".UPSTREAM_PROBE "
        "(PROBE_KEY, SOURCE_KEY, KIND, REQUEST_URL, HTTP_STATUS, OK, LATENCY_MS, "
        "SIGNAL_COUNT, ERROR_MESSAGE, PAYLOAD_BYTES, PAYLOAD_SAMPLE) "
        "SELECT ?, ?, ?, ?, TRY_TO_NUMBER(?), TRY_TO_BOOLEAN(?), TRY_TO_NUMBER(?), "
        "TRY_TO_NUMBER(?), ?, TRY_TO_NUMBER(?), ?",
        params=[pkey, _s(src_key), _s(kind), _s(url), _s(status), _s(bool(ok)), _s(ms),
                _s(nsig), _s(err), _s(nbytes), _s(sample)],
    ).collect()
    r = session.sql("SELECT PROBE_ID FROM " + SCHEMA_FQN + ".UPSTREAM_PROBE "
                    "WHERE PROBE_KEY = ?", params=[pkey]).collect()
    return r[0]["PROBE_ID"] if r else None


def _s(v):
    """Bind everything as text. A VALUES clause infers column types from the
    first row, so a running DAG with no duration would poison a numeric column
    for every row after it. Casting explicitly in the outer SELECT is the only
    way to make this deterministic."""
    if v is None:
        return None
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    return str(v)


def _write_signals(session, probe_id, src_key, kind, rows):
    if not rows:
        return 0
    written = 0
    for i in range(0, len(rows), 50):
        chunk = rows[i:i + 50]
        vals = []
        params = []
        for r in chunk:
            # No function calls inside VALUES — Snowflake rejects them there.
            vals.append("(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
            params.extend([
                _s(probe_id), _s(src_key), _s(kind),
                _s(r.get("entity"))[:512] if r.get("entity") is not None else None,
                _s(r.get("entity_kind")), _s(r.get("signal_name")), _s(r.get("state")),
                _s(bool(r.get("is_failing"))),
                _iso(r.get("observed_at")), _iso(r.get("last_success_at")),
                _s(r.get("staleness_sec")), _s(r.get("value_num")),
                json.dumps(r.get("detail") or {}, default=str)[:16000],
            ])
        session.sql(
            "INSERT INTO " + SCHEMA_FQN + ".UPSTREAM_SIGNAL "
            "(PROBE_ID, SOURCE_KEY, KIND, ENTITY, ENTITY_KIND, SIGNAL_NAME, STATE, "
            "IS_FAILING, OBSERVED_AT, LAST_SUCCESS_AT, STALENESS_SEC, VALUE_NUM, DETAIL) "
            "SELECT TRY_TO_NUMBER(column1), column2, column3, column4, column5, column6, "
            "column7, TRY_TO_BOOLEAN(column8), TRY_TO_TIMESTAMP_LTZ(column9), "
            "TRY_TO_TIMESTAMP_LTZ(column10), TRY_TO_NUMBER(column11), "
            "TRY_TO_DOUBLE(column12), TRY_PARSE_JSON(column13) FROM VALUES " + ", ".join(vals),
            params=params,
        ).collect()
        written += len(chunk)
    return written


def run(session, source_key):
    ref = _utcnow()
    rows = session.sql(
        "SELECT SOURCE_KEY, KIND, BASE_URL, SECRET_NAME, AUTH_KIND, CONFIG, "
        "STALENESS_WARN_SEC, STALENESS_CRIT_SEC FROM " + SCHEMA_FQN +
        ".UPSTREAM_SOURCE WHERE SOURCE_KEY = ?", params=[source_key]).collect()
    if not rows:
        return {"ok": False, "error": "unknown source_key: " + str(source_key)}
    r0 = rows[0]
    kind = str(r0["KIND"]).upper()
    base = str(r0["BASE_URL"])
    if base.endswith("/") and "?" not in base:
        base = base.rstrip("/")
    cfg = {}
    if r0["CONFIG"]:
        try:
            cfg = json.loads(r0["CONFIG"]) if isinstance(r0["CONFIG"], str) else dict(r0["CONFIG"])
        except Exception:
            cfg = {}

    slot = None
    if r0["SECRET_NAME"]:
        slot = "s_" + str(source_key).lower()
    try:
        basic, headers = _creds(slot, r0["AUTH_KIND"], cfg)
    except Exception as e:
        _write_probe(session, source_key, kind, base, None, False, None,
                     "secret_unavailable: " + str(e)[:400], None, None, 0)
        return {"ok": False, "source_key": source_key,
                "error": "secret_unavailable — did you call REBIND_UPSTREAM_COLLECTOR()? " + str(e)[:300]}

    headers["User-Agent"] = "Snowflake-Observability-Collector/1.0"
    headers["Accept"] = "application/json"
    timeout = int(cfg.get("timeout_sec") or 20)

    # Each kind resolves to a list of (url, method, json_body, parse_context).
    calls = []
    if kind == "AIRFLOW_DAG_RUNS":
        path = _path(cfg, "/api/v1/dags/~/dagRuns")
        qs = ""
        if not _overridden(cfg):
            lim = int(cfg.get("limit") or 100)
            qs = "?order_by=-start_date&limit=" + str(lim)
            for st in (cfg.get("states") or []):
                qs = qs + "&state=" + str(st)
        calls.append((base + path + qs, cfg.get("method") or "GET", cfg.get("body"), {}))
    elif kind == "AIRFLOW_DAGS":
        path = _path(cfg, "/api/v1/dags")
        qs = "" if _overridden(cfg) else "?limit=" + str(int(cfg.get("limit") or 100))
        calls.append((base + path + qs, cfg.get("method") or "GET", cfg.get("body"), {}))
    elif kind == "PROMETHEUS":
        path = _path(cfg, "/api/v1/query")
        for qspec in (cfg.get("queries") or []):
            expr = qspec.get("expr")
            if not expr:
                continue
            if _overridden(cfg):
                url = base + path
            else:
                url = base + path + "?query=" + requests.utils.quote(str(expr))
            calls.append((url, "GET", None, qspec))
    elif kind == "CONFLUENT_METRICS":
        path = _path(cfg, "/v2/metrics/cloud/query")
        cluster = cfg.get("cluster_id")
        jb = cfg.get("body") or {
            "aggregations": [{"metric": cfg.get("metric") or "io.confluent.kafka.server/consumer_lag_offsets"}],
            "filter": {"field": "resource.kafka.id", "op": "EQ", "value": cluster},
            "granularity": cfg.get("granularity") or "PT1M",
            "group_by": cfg.get("group_by") or ["metric.consumer_group_id", "metric.topic"],
            "intervals": cfg.get("intervals") or ["PT5M/now"],
            "limit": int(cfg.get("limit") or 200),
        }
        calls.append((base + path, "POST", jb, {}))
    elif kind == "HTTP_JSON":
        path = _path(cfg, "/")
        calls.append((base + path, cfg.get("method") or "GET", cfg.get("body"), {}))
    else:
        _write_probe(session, source_key, kind, base, None, False, None,
                     "unsupported kind: " + kind, None, None, 0)
        return {"ok": False, "source_key": source_key, "error": "unsupported kind: " + kind}

    total_signals = 0
    probes = []
    for (url, method, jbody, qspec) in calls:
        t0 = datetime.now(timezone.utc)
        status = None
        ok = False
        err = None
        sample = None
        nbytes = None
        parsed = []
        try:
            resp = _fetch(url, method, basic, headers, jbody, timeout)
            status = resp.status_code
            text = resp.text or ""
            nbytes = len(text.encode("utf-8", "ignore"))
            sample = text[:MAX_SAMPLE]
            if status >= 400:
                err = "http_" + str(status) + ": " + text[:300]
            else:
                try:
                    body = json.loads(text)
                except Exception as e:
                    body = None
                    err = "invalid_json: " + str(e)[:200]
                if body is not None:
                    if kind == "AIRFLOW_DAG_RUNS":
                        parsed = _parse_airflow_runs(body, ref, cfg)
                    elif kind == "AIRFLOW_DAGS":
                        parsed = _parse_airflow_dags(body, ref, cfg)
                    elif kind == "PROMETHEUS":
                        if str(_dig(body, "status") or "success") != "success":
                            err = "prometheus_error: " + str(body.get("error"))[:300]
                        else:
                            parsed = _parse_prometheus(body, ref, cfg, qspec)
                    elif kind == "CONFLUENT_METRICS":
                        parsed = _parse_confluent(body, ref, cfg)
                    else:
                        parsed = _parse_generic(body, ref, cfg)
                    ok = err is None
        except Exception as e:
            err = type(e).__name__ + ": " + str(e)[:400]
        ms = int((datetime.now(timezone.utc) - t0).total_seconds() * 1000)
        pid = _write_probe(session, source_key, kind, url, status, ok, ms, err,
                           nbytes, sample, len(parsed))
        if parsed:
            total_signals += _write_signals(session, pid, source_key, kind, parsed)
        probes.append({"url": url, "status": status, "ok": ok, "ms": ms,
                       "signals": len(parsed), "error": err})

    failing = 0
    for p in probes:
        if not p["ok"]:
            failing += 1
    return {"ok": failing == 0, "source_key": source_key, "kind": kind,
            "calls": len(calls), "failed_calls": failing,
            "signals_written": total_signals, "probes": probes}
';
  py := REPLACE(:py, '__TGT__', :tgt);

  -- Guard the embedding contract. If a single quote ever creeps into the body
  -- the generated DDL would terminate early and create a corrupt procedure.
  IF (POSITION('''' IN :py) > 0) THEN
    RETURN OBJECT_CONSTRUCT('block','BLOCK 3','status','ABORTED',
      'reason','collector body contains a single quote, which breaks SQL embedding');
  END IF;

  -- The collector, bound to the EAI. On first build no secrets are attached,
  -- because no source has been pointed at one yet.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE PROCEDURE ' || :tgt || '.COLLECT_UPSTREAM(P_SOURCE_KEY STRING) ' ||
    'RETURNS VARIANT LANGUAGE PYTHON RUNTIME_VERSION = ''3.11'' ' ||
    'PACKAGES = (''snowflake-snowpark-python'',''requests'') HANDLER = ''run'' ' ||
    'EXTERNAL_ACCESS_INTEGRATIONS = (' || :eai || ') AS ' || CHR(39) || :py || CHR(39));

  -- Regenerates the collector with SECRETS assembled from the registry. This is
  -- the workaround for SECRETS being fixed at CREATE time.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE PROCEDURE ' || :tgt || '.REBIND_UPSTREAM_COLLECTOR() ' ||
    'RETURNS VARCHAR LANGUAGE SQL EXECUTE AS CALLER AS DECLARE ' ||
    'sec VARCHAR DEFAULT ''''; body VARCHAR; ddl VARCHAR; cnt INT DEFAULT 0; BEGIN ' ||
    'SELECT LISTAGG('''''''' || ''s_'' || LOWER(SOURCE_KEY) || '''''''' || '' = '' || SECRET_NAME, '', '') ' ||
    'INTO sec FROM ' || :tgt || '.UPSTREAM_SOURCE WHERE SECRET_NAME IS NOT NULL AND ENABLED = TRUE; ' ||
    'SELECT COUNT(*) INTO cnt FROM ' || :tgt || '.UPSTREAM_SOURCE WHERE SECRET_NAME IS NOT NULL AND ENABLED = TRUE; ' ||
    'SELECT GET_DDL(''PROCEDURE'', ''' || :tgt || '.COLLECT_UPSTREAM(VARCHAR)'') INTO body; ' ||
    -- GET_DDL emits an unqualified name. Executing that from inside a procedure
    -- fails with "no current database", so qualify it before re-running.
    'body := REPLACE(body, ''PROCEDURE "COLLECT_UPSTREAM"'', ''PROCEDURE ' || :tgt || '."COLLECT_UPSTREAM"''); ' ||
    'body := REGEXP_REPLACE(body, ''\\\\sSECRETS\\\\s*=\\\\s*\\\\([^)]*\\\\)'', '' ''); ' ||
    'IF (:cnt > 0) THEN ddl := REGEXP_REPLACE(body, ''(EXTERNAL_ACCESS_INTEGRATIONS\\\\s*=\\\\s*\\\\([^)]*\\\\))'', ' ||
    '''\\\\1 SECRETS = ('' || :sec || '')''); ELSE ddl := body; END IF; ' ||
    'EXECUTE IMMEDIATE :ddl; ' ||
    'RETURN ''rebound: '' || :cnt || '' secret(s), secrets_clause_present='' || ' ||
    '(POSITION(''SECRETS ='' IN :ddl) > 0)::VARCHAR; END');

  -- Loop enabled sources. Isolated failures must not stop the sweep.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE PROCEDURE ' || :tgt || '.COLLECT_ALL_UPSTREAM() ' ||
    'RETURNS VARIANT LANGUAGE SQL EXECUTE AS CALLER AS DECLARE ' ||
    'res ARRAY DEFAULT ARRAY_CONSTRUCT(); okc INT DEFAULT 0; badc INT DEFAULT 0; ' ||
    'cur CURSOR FOR SELECT SOURCE_KEY FROM ' || :tgt || '.UPSTREAM_SOURCE WHERE ENABLED = TRUE; BEGIN ' ||
    'FOR rec IN cur DO LET k VARCHAR := rec.SOURCE_KEY; ' ||
    'BEGIN LET r VARIANT; CALL ' || :tgt || '.COLLECT_UPSTREAM(:k) INTO :r; ' ||
    'IF (:r:ok = TRUE) THEN okc := :okc + 1; ELSE badc := :badc + 1; END IF; ' ||
    'res := ARRAY_APPEND(:res, :r); ' ||
    'EXCEPTION WHEN OTHER THEN badc := :badc + 1; ' ||
    'res := ARRAY_APPEND(:res, OBJECT_CONSTRUCT(''source_key'', :k, ''ok'', FALSE, ''error'', SQLERRM)); END; ' ||
    'END FOR; ' ||
    'RETURN OBJECT_CONSTRUCT(''sources_ok'', :okc, ''sources_failed'', :badc, ''results'', :res); END');

  -- Latest observation per entity per signal. Partitioning on SIGNAL_NAME as
  -- well as ENTITY matters: one Prometheus source asks several questions about
  -- the same instance, and without it the answers overwrite each other.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE VIEW ' || :tgt || '.V_UPSTREAM_HEALTH AS ' ||
    'WITH ranked AS (SELECT s.*, p.PROBE_AT, ROW_NUMBER() OVER (PARTITION BY s.SOURCE_KEY, ' ||
    's.ENTITY, s.ENTITY_KIND, COALESCE(s.SIGNAL_NAME,''default'') ' ||
    'ORDER BY p.PROBE_AT DESC NULLS LAST, s.SIGNAL_AT DESC) AS RN ' ||
    'FROM ' || :tgt || '.UPSTREAM_SIGNAL s ' ||
    'LEFT JOIN ' || :tgt || '.UPSTREAM_PROBE p ON p.PROBE_ID = s.PROBE_ID) ' ||
    'SELECT r.SOURCE_KEY, r.KIND, r.ENTITY, r.ENTITY_KIND, r.SIGNAL_NAME, r.STATE, r.IS_FAILING, ' ||
    'r.OBSERVED_AT, r.LAST_SUCCESS_AT, r.STALENESS_SEC, r.VALUE_NUM, r.SIGNAL_AT AS OBSERVED_BY_SNOWFLAKE_AT, ' ||
    'src.STALENESS_WARN_SEC, src.STALENESS_CRIT_SEC, ' ||
    -- Severity must respect the grade the parser already assigned. A source
    -- that returned "warning" cannot be reported as OK.
    'CASE WHEN r.IS_FAILING THEN ''CRITICAL'' ' ||
    'WHEN LOWER(r.STATE) IN (''failed'',''critical'') THEN ''CRITICAL'' ' ||
    'WHEN r.STALENESS_SEC > src.STALENESS_CRIT_SEC THEN ''CRITICAL'' ' ||
    'WHEN LOWER(r.STATE) IN (''warning'',''upstream_failed'',''restarting'') THEN ''WARNING'' ' ||
    'WHEN r.STALENESS_SEC > src.STALENESS_WARN_SEC THEN ''WARNING'' ' ||
    'ELSE ''OK'' END AS SEVERITY, r.DETAIL ' ||
    'FROM ranked r LEFT JOIN ' || :tgt || '.UPSTREAM_SOURCE src USING (SOURCE_KEY) WHERE r.RN = 1');

  -- Entities past their staleness budget. This is the alertable surface.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE VIEW ' || :tgt || '.V_UPSTREAM_STALE AS ' ||
    'SELECT * FROM ' || :tgt || '.V_UPSTREAM_HEALTH WHERE SEVERITY IN (''WARNING'',''CRITICAL'')');

  -- Collector self-observability: a source that stopped answering at all.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE VIEW ' || :tgt || '.V_UPSTREAM_COLLECTOR_HEALTH AS ' ||
    'SELECT src.SOURCE_KEY, src.KIND, src.ENABLED, src.POLL_MINUTES, ' ||
    'MAX(p.PROBE_AT) AS LAST_PROBE_AT, ' ||
    'DATEDIFF(SECOND, MAX(p.PROBE_AT), CURRENT_TIMESTAMP()) AS SECONDS_SINCE_PROBE, ' ||
    'MAX(CASE WHEN p.OK THEN p.PROBE_AT END) AS LAST_SUCCESSFUL_PROBE_AT, ' ||
    'COUNT_IF(NOT p.OK AND p.PROBE_AT >= DATEADD(HOUR,-24,CURRENT_TIMESTAMP())) AS FAILED_PROBES_24H, ' ||
    'COUNT_IF(p.PROBE_AT >= DATEADD(HOUR,-24,CURRENT_TIMESTAMP())) AS PROBES_24H, ' ||
    'MAX(CASE WHEN NOT p.OK THEN p.ERROR_MESSAGE END) AS LAST_ERROR, ' ||
    'CASE WHEN src.ENABLED = FALSE THEN ''DISABLED'' ' ||
    'WHEN MAX(p.PROBE_AT) IS NULL THEN ''NEVER_POLLED'' ' ||
    'WHEN DATEDIFF(SECOND, MAX(p.PROBE_AT), CURRENT_TIMESTAMP()) > src.POLL_MINUTES * 180 THEN ''COLLECTOR_STALLED'' ' ||
    'WHEN MAX(CASE WHEN p.OK THEN p.PROBE_AT END) IS NULL THEN ''NEVER_SUCCEEDED'' ' ||
    'ELSE ''OK'' END AS COLLECTOR_STATE ' ||
    'FROM ' || :tgt || '.UPSTREAM_SOURCE src LEFT JOIN ' || :tgt || '.UPSTREAM_PROBE p USING (SOURCE_KEY) ' ||
    'GROUP BY src.SOURCE_KEY, src.KIND, src.ENABLED, src.POLL_MINUTES');

  -- Bridge into the existing incident lifecycle when Block 2 built it. An
  -- upstream failure then gets the same triage, grouping and routing as a DMF
  -- anomaly, rather than a parallel notification path nobody maintains.
  IF (:has_incidents) THEN
    stmts := ARRAY_APPEND(:stmts,
      'CREATE OR REPLACE PROCEDURE ' || :tgt || '.RAISE_UPSTREAM_INCIDENTS() ' ||
      'RETURNS VARIANT LANGUAGE SQL EXECUTE AS CALLER AS DECLARE ' ||
      'raised INT DEFAULT 0; skipped INT DEFAULT 0; errs ARRAY DEFAULT ARRAY_CONSTRUCT(); ' ||
      'cur CURSOR FOR SELECT SOURCE_KEY, ENTITY, ENTITY_KIND, SIGNAL_NAME, STATE, SEVERITY ' ||
      'FROM ' || :tgt || '.V_UPSTREAM_HEALTH WHERE SEVERITY IN (''WARNING'',''CRITICAL''); BEGIN ' ||
      'FOR rec IN cur DO ' ||
      -- Cursor fields are not accepted as CALL arguments, so bind them first.
      'LET fqn VARCHAR := ''upstream://'' || rec.SOURCE_KEY || ''/'' || rec.ENTITY_KIND || ''/'' || rec.ENTITY; ' ||
      'LET sig VARCHAR := IFF(LOWER(rec.STATE) = ''failed'', ''upstream_failure'', ''upstream_staleness''); ' ||
      -- METRIC_NAME carries the signal name, so two different signals about the
      -- same entity stay two incidents instead of colliding on one fingerprint.
      'LET met VARCHAR := COALESCE(rec.SIGNAL_NAME, rec.STATE); ' ||
      'LET sev VARCHAR := rec.SEVERITY; ' ||
      'BEGIN CALL ' || :tgt || '.RECORD_INCIDENT(:sig, :fqn, :met, :sev); raised := :raised + 1; ' ||
      -- Report what was dropped and why. A bridge that silently swallows
      -- failures is indistinguishable from one that is not running.
      'EXCEPTION WHEN OTHER THEN skipped := :skipped + 1; ' ||
      'IF (ARRAY_SIZE(:errs) < 10) THEN errs := ARRAY_APPEND(:errs, ' ||
      'OBJECT_CONSTRUCT(''object'', :fqn, ''error'', SQLERRM)); END IF; END; ' ||
      'END FOR; ' ||
      'RETURN OBJECT_CONSTRUCT(''incidents_raised'', :raised, ''skipped'', :skipped, ' ||
      '''errors'', :errs); END');
  ELSE
    notes := ARRAY_APPEND(:notes,
      'Block 2 incident lifecycle not found in ' || :tgt || ', so RAISE_UPSTREAM_INCIDENTS was ' ||
      'not created. Upstream signals are still queryable in V_UPSTREAM_HEALTH.');
  END IF;

  -- Poller. Created suspended: a task that starts polling the moment a script
  -- finishes is a surprise, and this one makes outbound network calls.
  stmts := ARRAY_APPEND(:stmts,
    'CREATE OR REPLACE TASK ' || :tgt || '.TASK_COLLECT_UPSTREAM ' ||
    IFF(:wh = '', '', 'WAREHOUSE = ' || :wh || ' ') ||
    'SCHEDULE = ''10 MINUTE'' ' ||
    'ALLOW_OVERLAPPING_EXECUTION = FALSE ' ||
    'SUSPEND_TASK_AFTER_NUM_FAILURES = 10 ' ||
    'AS BEGIN CALL ' || :tgt || '.COLLECT_ALL_UPSTREAM(); ' ||
    IFF(:has_incidents, 'CALL ' || :tgt || '.RAISE_UPSTREAM_INCIDENTS(); ', '') ||
    'END');

  -- Worked examples. Disabled, with placeholder hosts, so the registry is
  -- self-documenting without ever pointing at something real.
  IF (:seed) THEN
    stmts := ARRAY_APPEND(:stmts,
      'MERGE INTO ' || :tgt || '.UPSTREAM_SOURCE t USING (SELECT ''airflow_prod'' AS K) s ON t.SOURCE_KEY = s.K ' ||
      'WHEN NOT MATCHED THEN INSERT (SOURCE_KEY, KIND, BASE_URL, AUTH_KIND, ENABLED, POLL_MINUTES, ' ||
      'STALENESS_WARN_SEC, STALENESS_CRIT_SEC, CONFIG, DESCRIPTION) VALUES (''airflow_prod'', ' ||
      '''AIRFLOW_DAG_RUNS'', ''https://airflow.internal.example.com'', ''BASIC'', FALSE, 10, 3600, 10800, ' ||
      'PARSE_JSON(''{"limit":100,"timeout_sec":20}''), ' ||
      '''Latest run state per DAG. The failure signal external lineage cannot give.'')');
    stmts := ARRAY_APPEND(:stmts,
      'MERGE INTO ' || :tgt || '.UPSTREAM_SOURCE t USING (SELECT ''airflow_prod_dags'' AS K) s ON t.SOURCE_KEY = s.K ' ||
      'WHEN NOT MATCHED THEN INSERT (SOURCE_KEY, KIND, BASE_URL, AUTH_KIND, ENABLED, POLL_MINUTES, CONFIG, DESCRIPTION) ' ||
      'VALUES (''airflow_prod_dags'', ''AIRFLOW_DAGS'', ''https://airflow.internal.example.com'', ''BASIC'', FALSE, 60, ' ||
      'PARSE_JSON(''{"limit":200,"paused_is_failing":false}''), ' ||
      '''Paused/active per DAG. A silently paused DAG looks identical to a healthy idle one.'')');
    stmts := ARRAY_APPEND(:stmts,
      'MERGE INTO ' || :tgt || '.UPSTREAM_SOURCE t USING (SELECT ''postgres_exporter'' AS K) s ON t.SOURCE_KEY = s.K ' ||
      'WHEN NOT MATCHED THEN INSERT (SOURCE_KEY, KIND, BASE_URL, AUTH_KIND, ENABLED, POLL_MINUTES, CONFIG, DESCRIPTION) ' ||
      'VALUES (''postgres_exporter'', ''PROMETHEUS'', ''https://prometheus.internal.example.com'', NULL, FALSE, 5, ' ||
      'PARSE_JSON(''{"entity_label":"instance","entity_kind":"postgres_instance","queries":[' ||
      '{"name":"replication_lag_sec","expr":"pg_replication_lag","warn":30,"crit":300},' ||
      '{"name":"replication_slot_bytes","expr":"pg_replication_slot_lag_bytes","warn":1073741824,"crit":10737418240},' ||
      '{"name":"dead_tuples","expr":"pg_stat_user_tables_n_dead_tup","warn":1000000,"crit":10000000},' ||
      '{"name":"seconds_since_vacuum","expr":"time() - pg_stat_user_tables_last_autovacuum","warn":86400,"crit":604800}' ||
      ']}''), ' ||
      '''Postgres replication lag, slot growth, bloat and vacuum age via postgres_exporter.'')');
    stmts := ARRAY_APPEND(:stmts,
      'MERGE INTO ' || :tgt || '.UPSTREAM_SOURCE t USING (SELECT ''confluent_lag'' AS K) s ON t.SOURCE_KEY = s.K ' ||
      'WHEN NOT MATCHED THEN INSERT (SOURCE_KEY, KIND, BASE_URL, SECRET_NAME, AUTH_KIND, ENABLED, POLL_MINUTES, CONFIG, DESCRIPTION) ' ||
      'VALUES (''confluent_lag'', ''CONFLUENT_METRICS'', ''https://api.telemetry.confluent.cloud'', NULL, ''BASIC'', FALSE, 5, ' ||
      'PARSE_JSON(''{"cluster_id":"lkc-xxxxx","metric":"io.confluent.kafka.server/consumer_lag_offsets",' ||
      '"warn":100000,"crit":1000000,"group_by":["metric.consumer_group_id","metric.topic"],"intervals":["PT5M/now"]}''), ' ||
      '''Consumer group lag per topic. Confirmed present in the live Confluent metric catalogue.'')');
  END IF;

  -- ------------------------------------------------------------- execute all
  n := ARRAY_SIZE(:stmts);
  FOR i IN 0 TO :n - 1 DO
    s := GET(:stmts, :i)::VARCHAR;
    BEGIN
      EXECUTE IMMEDIATE :s;
      created := :created + 1;
    EXCEPTION WHEN OTHER THEN
      failed := :failed + 1;
      errs := ARRAY_APPEND(:errs, OBJECT_CONSTRUCT('stmt', LEFT(:s, 180), 'error', SQLERRM));
    END;
  END FOR;

  RETURN OBJECT_CONSTRUCT(
    'block', 'BLOCK 3 · UPSTREAM COLLECTORS',
    'status', IFF(:failed = 0, 'BUILT', 'BUILT WITH ERRORS'),
    'target_schema', :tgt,
    'external_access_integration', :eai,
    'task_compute', IFF(:wh = '', 'serverless (needs EXECUTE MANAGED TASK)', 'warehouse ' || :wh),
    'statements_executed', :created,
    'statements_failed', :failed,
    'errors', :errs,
    'incident_bridge', IFF(:has_incidents, 'RAISE_UPSTREAM_INCIDENTS wired to RECORD_INCIDENT', 'not created'),
    'next_steps', ARRAY_CONSTRUCT(
      'Point a source at a real host and secret, then CALL ' || :tgt || '.REBIND_UPSTREAM_COLLECTOR()',
      'CALL ' || :tgt || '.COLLECT_ALL_UPSTREAM() to poll once',
      'SELECT * FROM ' || :tgt || '.V_UPSTREAM_HEALTH to see state per DAG, topic or instance',
      'SELECT * FROM ' || :tgt || '.V_UPSTREAM_COLLECTOR_HEALTH to confirm the collector itself is alive',
      'ALTER TASK ' || :tgt || '.TASK_COLLECT_UPSTREAM RESUME when you want continuous polling'),
    'constraints', :notes);
END;
$$;
